//! `ToArgv` must remain the exact inverse of clap's parsing.
//!
//! The GUI builds an argv and hands it to the CLI, which parses it again. If `to_argv` ever
//! stops agreeing with the parser — a renamed flag, a value written in the wrong position —
//! the failure would show up as a confusing runtime error in a window rather than as a test.
//! These tests hold the two ends together.

use clap::Parser;
use evmedia_contract::*;
use std::path::PathBuf;

fn path(value: &str) -> PathBuf {
    PathBuf::from(value)
}

/// A maximally-populated command for each subcommand: every flag set, every option non-default.
fn sample(name: &str) -> Command {
    match name {
        "tree" => Command::Tree(TreeArgs { catalog: path("examples/catalog.json") }),
        "download" => Command::Download(DownloadArgs {
            manifest: path("manifest.json"),
            output: path("out"),
            parallel: 4,
        }),
        "decode-ev" => Command::DecodeEv(DecodeEvArgs {
            input: path("segments"),
            manifest: path("captured.json"),
            output: path("lesson.ts"),
        }),
        "capture-ev" => Command::CaptureEv(CaptureEvArgs {
            pid: 4242,
            input: path("segments"),
            output: path("captured.json"),
        }),
        "grab" => Command::Grab(GrabArgs {
            pid: 4242,
            output: path("grab_out"),
            jobs: 4,
            poll: 2,
            idle_limit: 3,
            attempts: 2,
            no_sweep: true,
            sweep_gap_ms: 10,
            mp4: true,
        }),
        "adapters" => Command::Adapters(AdaptersArgs {}),
        "recover" => Command::Recover(RecoverArgs {
            pid: Some(4242),
            cache: path("D:/Downloads/EVPlayer2Downloads"),
            output: path("recover_out"),
            mp4: true,
            sweep: true,
            sweep_batch: 20,
            sweep_gap_ms: 100,
            sweep_idle: 3,
        }),
        other => panic!("subcommand `{other}` has no sample; add one so it stays covered"),
    }
}

fn parse(argv: &[String]) -> Cli {
    Cli::try_parse_from(std::iter::once("evmedia".to_string()).chain(argv.iter().cloned()))
        .unwrap_or_else(|error| panic!("argv {argv:?} did not parse: {error}"))
}

#[test]
fn every_subcommand_round_trips_through_argv() {
    for spec in describe() {
        let command = sample(&spec.name);
        let argv = command.to_argv();
        assert_eq!(argv.first().map(String::as_str), Some(spec.name.as_str()));
        assert_eq!(parse(&argv).command, command, "argv {argv:?} did not round-trip");
    }
}

#[test]
fn every_valued_option_is_written_exactly_once() {
    for spec in describe() {
        let argv = sample(&spec.name).to_argv();
        for arg in &spec.args {
            if arg.boolean {
                // A flag carries meaning only by being present, so it is written when set and
                // omitted otherwise; the sample sets every flag, so it must be here.
                let flag = format!("--{}", arg.long.as_deref().expect("flags have a long name"));
                assert_eq!(
                    argv.iter().filter(|token| **token == flag).count(),
                    1,
                    "{}: {flag} should appear exactly once in {argv:?}",
                    spec.name
                );
                continue;
            }
            let Some(long) = arg.long.as_deref() else {
                continue; // positional
            };
            let flag = format!("--{long}");
            assert_eq!(
                argv.iter().filter(|token| **token == flag).count(),
                1,
                "{}: {flag} should appear exactly once in {argv:?}",
                spec.name
            );
        }
    }
}

#[test]
fn positional_arguments_are_present_and_ordered() {
    for spec in describe() {
        let argv = sample(&spec.name).to_argv();
        let positionals: Vec<&String> = argv
            .iter()
            .skip(1)
            .filter(|token| !token.starts_with("--"))
            .collect();
        let expected = spec.args.iter().filter(|arg| arg.positional).count();
        // Values of `--flag value` pairs also land in this list, so only check that the count of
        // positional-shaped tokens is at least the number of real positionals.
        assert!(
            positionals.len() >= expected,
            "{}: expected at least {expected} positional token(s) in {argv:?}",
            spec.name
        );
    }
}

/// The GUI renders its forms from `describe`, so a subcommand missing there would be invisible.
#[test]
fn describe_covers_every_subcommand_the_parser_accepts() {
    let described: Vec<String> = describe().into_iter().map(|spec| spec.name).collect();
    let declared: Vec<String> = command()
        .get_subcommands()
        .map(|sub| sub.get_name().to_string())
        .collect();
    assert_eq!(described, declared);
    for expected in ["tree", "download", "decode-ev", "capture-ev", "grab", "recover", "adapters"] {
        assert!(described.contains(&expected.to_string()), "missing {expected}");
    }
}

/// The GUI adds these itself; if they became form fields the user could set them twice.
#[test]
fn the_gui_owned_flags_are_not_offered_as_fields() {
    for spec in describe() {
        for arg in &spec.args {
            assert!(
                !matches!(arg.id.as_str(), "json_events" | "stop_file" | "help" | "version"),
                "{}: {} should not be a form field",
                spec.name,
                arg.id
            );
        }
    }
}

/// The GUI shows these in placeholders and leaves the field empty so the CLI applies them. If a
/// reported default ever disagreed with the parsed one, the window would be lying about what
/// running the command will do.
#[test]
fn reported_defaults_match_what_the_parser_applies() {
    let specs = describe();
    let default_of = |command: &str, id: &str| {
        specs
            .iter()
            .find(|spec| spec.name == command)
            .and_then(|spec| spec.args.iter().find(|arg| arg.id == id))
            .and_then(|arg| arg.default.clone())
    };

    let Command::Grab(args) = parse(&["grab".to_string(), "--pid".to_string(), "7".to_string()]).command
    else {
        panic!("expected a grab command");
    };
    assert_eq!(default_of("grab", "jobs").as_deref(), Some(args.jobs.to_string().as_str()));
    assert_eq!(default_of("grab", "poll").as_deref(), Some(args.poll.to_string().as_str()));
    assert_eq!(
        default_of("grab", "idle_limit").as_deref(),
        Some(args.idle_limit.to_string().as_str())
    );
    assert_eq!(default_of("grab", "attempts").as_deref(), Some(args.attempts.to_string().as_str()));
    assert_eq!(
        default_of("grab", "sweep_gap_ms").as_deref(),
        Some(args.sweep_gap_ms.to_string().as_str())
    );
    assert_eq!(
        default_of("grab", "output").as_deref(),
        Some(args.output.to_string_lossy().to_string().as_str())
    );

    let Command::Download(args) =
        parse(&["download".to_string(), "m.json".to_string(), "out".to_string()]).command
    else {
        panic!("expected a download command");
    };
    assert_eq!(
        default_of("download", "parallel").as_deref(),
        Some(args.parallel.to_string().as_str())
    );
}

#[test]
fn a_missing_required_argument_is_a_parse_error() {
    let outcome = Cli::try_parse_from(["evmedia", "grab"]);
    assert!(outcome.is_err(), "grab without --pid must not parse");
}

//! A JSON description of the CLI surface, derived from the clap definition at runtime.
//!
//! The GUI builds its forms from this instead of from a hand-written list of fields, so a new
//! flag, a renamed option or a changed default appears in the window without anyone having to
//! remember to update a second copy. It is also what makes "the GUI runs the CLI" checkable:
//! every widget on screen exists because the CLI accepts that argument.

use serde::Serialize;

/// Arguments the GUI supplies itself, or that clap adds, and which must not become form fields.
const NOT_A_FORM_FIELD: &[&str] = &["help", "version", "json_events", "stop_file"];

/// Argument ids that are numbers even though their default does not look like one.
const NUMERIC_IDS: &[&str] = &[
    "pid",
    "jobs",
    "poll",
    "idle_limit",
    "attempts",
    "sweep_gap_ms",
    "sweep_batch",
    "sweep_idle",
    "parallel",
];

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct ArgSpec {
    pub id: String,
    pub long: Option<String>,
    pub help: String,
    /// clap's declared default, or `None` when the argument is optional and unset by default.
    pub default: Option<String>,
    pub required: bool,
    /// Positional arguments are rendered as plain fields; the rest get a `--flag`.
    pub positional: bool,
    /// A flag that carries no value of its own.
    pub boolean: bool,
    /// The form should validate this as a number.
    pub numeric: bool,
    /// The form should offer a file/folder picker.
    pub path: bool,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct CommandSpec {
    pub name: String,
    pub about: String,
    pub args: Vec<ArgSpec>,
}

fn looks_like_a_path(id: &str) -> bool {
    ["input", "output", "manifest", "catalog"]
        .iter()
        .any(|needle| id.contains(needle))
}

pub fn describe() -> Vec<CommandSpec> {
    crate::args::command()
        .get_subcommands()
        .map(|sub| CommandSpec {
            name: sub.get_name().to_string(),
            about: sub.get_about().map(|about| about.to_string()).unwrap_or_default(),
            args: sub
                .get_arguments()
                .filter_map(|arg| {
                    let id = arg.get_id().to_string();
                    if NOT_A_FORM_FIELD.contains(&id.as_str()) {
                        return None;
                    }
                    let boolean = matches!(arg.get_action(), clap::ArgAction::SetTrue);
                    let default = arg
                        .get_default_values()
                        .first()
                        .map(|value| value.to_string_lossy().into_owned());
                    let numeric = !boolean
                        && (NUMERIC_IDS.contains(&id.as_str())
                            || default.as_deref().is_some_and(|d| d.parse::<f64>().is_ok()));
                    Some(ArgSpec {
                        long: arg.get_long().map(str::to_string),
                        help: arg.get_help().map(|help| help.to_string()).unwrap_or_default(),
                        required: arg.is_required_set(),
                        positional: arg.is_positional(),
                        numeric,
                        path: !boolean && looks_like_a_path(&id),
                        boolean,
                        default,
                        id,
                    })
                })
                .collect(),
        })
        .collect()
}

//! One function per subcommand. `grab` and `capture-ev` are the only two that differ by
//! platform; everything else is portable.

use anyhow::Result;
#[cfg(not(windows))]
use anyhow::bail;
use evmedia_contract::{
    CaptureEvArgs, Command, Event, GrabArgs, RecoverArgs, Reporter, Stage, StageState,
};
use evmedia_core::{catalog, decode, download, harvest, keyscan, media, read_json};
use evmedia_core::keyscan::KeyEntry;
use std::time::Duration;

const ADAPTERS: &str = "evplayer2-5.0.5/windows-live-manifest\ngeneric/http-segment-manifest\nandroid-agent-protocol (planned)\nmacos-agent-protocol (planned)\nios-companion-app-protocol (planned)";

pub async fn dispatch(command: Command, reporter: &Reporter) -> Result<()> {
    match command {
        Command::Tree(args) => catalog::run(&args.catalog, reporter),
        Command::Download(args) => {
            let manifest: download::DownloadManifest = read_json(&args.manifest)?;
            download::download_all(manifest, args.output, args.parallel, reporter).await
        }
        Command::DecodeEv(args) => {
            let manifest: decode::EvManifest = read_json(&args.manifest)?;
            decode::decode_ev(&args.input, manifest, &args.output, reporter)
        }
        Command::CaptureEv(args) => capture_ev(args, reporter),
        Command::Grab(args) => grab(args, reporter),
        Command::Recover(args) => recover(args, reporter),
        Command::Adapters(_) => {
            reporter.info(ADAPTERS);
            Ok(())
        }
    }
}

#[cfg(windows)]
fn capture_ev(args: CaptureEvArgs, reporter: &Reporter) -> Result<()> {
    evmedia_win::capture::capture(args.pid, &args.input, &args.output, reporter)
}

#[cfg(not(windows))]
fn capture_ev(args: CaptureEvArgs, reporter: &Reporter) -> Result<()> {
    let _ = (args, reporter);
    bail!("capture-ev is only available in the Windows EVPlayer2 adapter");
}

#[cfg(windows)]
fn grab(args: GrabArgs, reporter: &Reporter) -> Result<()> {
    let source = evmedia_win::WinSource::open(args.pid)?;
    let options = harvest::GrabOptions {
        output: args.output,
        jobs: args.jobs,
        poll: Duration::from_secs(args.poll),
        idle_limit: args.idle_limit,
        attempts: args.attempts,
        mp4: args.mp4,
        sweep: !args.no_sweep,
        press_gap: Duration::from_millis(args.sweep_gap_ms),
    };
    harvest::grab::run(&source, &options, reporter)
}

#[cfg(not(windows))]
fn grab(args: GrabArgs, reporter: &Reporter) -> Result<()> {
    let _ = (args, reporter);
    bail!("grab is only available in the Windows EVPlayer2 adapter");
}

#[cfg(windows)]
fn recover(args: RecoverArgs, reporter: &Reporter) -> Result<()> {
    let Some(pid) = args.pid.or_else(evmedia_win::find_player_pid) else {
        anyhow::bail!("EVPlayer2 is not running; start it, play the lesson, then rerun");
    };
    let source = evmedia_win::WinSource::open(pid)?;
    let player = source.player();

    // The library persists across runs. A sweep that is interrupted, or a player that restarts,
    // must not cost the keys already paid for -- and a segment already solved never needs testing
    // again, which is what keeps a resumed sweep cheap.
    let library_path = args.output.join("keys.json");
    let mut library = keyscan::load_library(&library_path);
    reporter.info(format!(
        "pid {pid}; {} key(s) already known",
        library.len()
    ));

    reporter.event(&Event::Stage {
        name: Stage::Scan,
        state: StageState::Begin,
        detail: if args.sweep { "sweeping the playhead" } else { "reading keys" }.to_string(),
    });

    if args.sweep {
        let options = evmedia_win::sweep::SweepOptions {
            batch: args.sweep_batch,
            gap: Duration::from_millis(args.sweep_gap_ms),
            idle_rounds: args.sweep_idle,
            ..Default::default()
        };
        let gained = evmedia_win::sweep::collect(player, &args.cache, &mut library, &options, reporter)?;
        reporter.info(format!("the sweep added {gained} key(s)"));
    } else {
        // Report the candidate count separately from the hit count. Without it, a scan that found
        // nothing to look at is indistinguishable from a scan that looked and found no key.
        let candidates = player.hex_candidates();
        reporter.info(format!("{} 32-hex candidate(s) in memory", candidates.len()));
        let found = player.recover_pairs(&args.cache, &candidates, &library);
        reporter.info(format!("{} key(s) live right now", found.len()));
        for (file, key) in found {
            library.entry(file).or_insert(KeyEntry { key, index: None, lesson: None });
        }
        player.fill_metadata(&mut library);
    }

    reporter.event(&Event::Stage {
        name: Stage::Scan,
        state: StageState::End,
        detail: format!("{} key(s)", library.len()),
    });
    keyscan::save_library(&library_path, &library)?;

    if library.is_empty() {
        reporter.info(
            "Nothing was recoverable. The player computes a segment's key only while it decrypts \
             that segment for playback, and it downloads without ever computing one -- so the \
             lesson has to be played, or swept with --sweep, before any key exists to read."
                .to_string(),
        );
        return Ok(());
    }

    // One output tree per lesson. This is not cosmetic: segment indexes restart at 0 for every
    // lesson, so decrypting and merging the whole library at once would overwrite one lesson's
    // segments with another's and produce a file that looks fine and is the wrong length.
    let groups = keyscan::group_by_lesson(&library);
    for (lesson, group) in &groups {
        let lesson_dir = if groups.len() == 1 {
            args.output.clone()
        } else {
            args.output.join(format!("lesson-{lesson}"))
        };
        let dec_dir = lesson_dir.join("dec");
        let written = keyscan::decrypt_into(&args.cache, &dec_dir, &group.entries)?;
        reporter.info(format!(
            "lesson {lesson}: decrypted {written}/{} segment(s)",
            group.entries.len()
        ));

        if !group.placed {
            reporter.info(format!(
                "  lesson {lesson} is not merged: its segments have no index the player can still \
                 name (their URLs are long gone), so their order is unknown. The decrypted files \
                 are in {}",
                dec_dir.display()
            ));
            continue;
        }

        // `entries` is a BTreeMap, so indexes arrive sorted — which the merge depends on, since it
        // concatenates in the order given and decides completeness from the highest index.
        let indexes: Vec<u32> = group.entries.keys().copied().collect();
        let merged = media::merge_lesson(&dec_dir, &lesson_dir, &indexes, reporter)?;
        if args.mp4 {
            media::remux_mp4(&merged.path, &lesson_dir.join("lesson.mp4"), reporter)?;
        }
    }
    Ok(())
}

#[cfg(not(windows))]
fn recover(args: RecoverArgs, reporter: &Reporter) -> Result<()> {
    let _ = (args, reporter);
    bail!("recover is only available in the Windows EVPlayer2 adapter");
}

//! Turning candidate keys into open segments.
//!
//! While the player has a segment decrypted for playback, its key sits in the heap as **32 hex
//! characters** of plain text. The key never crosses the network -- the API hands out `tk`, which
//! is not the key -- so the process's own memory is the only place it exists.
//!
//! Which segment a key belongs to needs no knowledge of memory layout at all: try the key on the
//! segment's bytes and see whether MPEG-TS falls out. That check is what makes this reliable --
//! struct offsets change between builds, AES does not.

use crate::crypto::{decrypt, key_from_text, mask_from_filename};
use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};
use std::io::Read;
use std::path::Path;

/// One segment's key, plus the two things needed to place it: which lesson it belongs to, and
/// where inside that lesson it sits.
///
/// The lesson is not decoration. Segment indexes restart at 0 for every lesson, so merging by
/// index alone silently stitches two lessons together — the filename is a globally unique UUID,
/// the index is not. That failure is quiet: the merge succeeds and produces a file of the wrong
/// length.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq)]
pub struct KeyEntry {
    pub key: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub index: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lesson: Option<String>,
}

/// Segment filename -> its key entry.
///
/// Keyed by filename because that is the one identifier unique across lessons, so the library
/// stays valid when the player is restarted or moved to a different lesson.
pub type Library = BTreeMap<String, KeyEntry>;

/// Reads either the current entry shape or the older `filename -> "key"` one, so a library
/// written by an earlier build still loads instead of being silently thrown away.
#[derive(Deserialize)]
#[serde(untagged)]
enum RawEntry {
    Plain(String),
    Full(KeyEntry),
}

impl From<RawEntry> for KeyEntry {
    fn from(raw: RawEntry) -> Self {
        match raw {
            RawEntry::Plain(key) => KeyEntry { key, index: None, lesson: None },
            RawEntry::Full(entry) => entry,
        }
    }
}

/// How much of a segment to read when testing a key.
///
/// Must be a multiple of both 188 and 16: 188 is 4·47, so 188·4 = 752 is the smallest number
/// satisfying both. **Do not use 376.** It is 2·188 but not a multiple of 16, so AES rejects it
/// as unaligned -- and once that error is swallowed, every key looks like a wrong key and the
/// whole round of testing comes back as a false negative.
pub const PROBE_BYTES: usize = 188 * 4;

/// Does this candidate key open this segment?
///
/// `head` should be [`PROBE_BYTES`] long. Anything shorter returns false rather than erroring,
/// because a directory mid-download has half-written files in it.
pub fn opens(filename: &str, key_text: &str, head: &[u8]) -> bool {
    if head.len() < PROBE_BYTES {
        return false;
    }
    let Ok(key) = key_from_text(key_text) else {
        return false;
    };
    let mask = mask_from_filename(filename);
    decrypt(head, &key, &mask, filename).is_ok()
}

/// Find the key for every segment in `dir` that one of `candidates` opens, skipping anything
/// already in `skip`.
///
/// Returns filename -> key, holding only segments that actually opened. One key may open several
/// segments and each is recorded: keys are genuinely reused across some segments.
///
/// The `skip` set is what makes a sweep affordable. A sweep re-tests on every round, so testing
/// all candidates against all segments each time would cost tens of millions of AES calls per
/// round; segments already solved cannot become unsolved, and only the handful of *new* candidates
/// can open anything, so each round only pays for (new candidates x unsolved segments).
pub fn recover(
    dir: &Path,
    candidates: &BTreeSet<String>,
    skip: &Library,
) -> Result<BTreeMap<String, String>> {
    let mut out = BTreeMap::new();
    for entry in std::fs::read_dir(dir)? {
        let path = entry?.path();
        if path.extension().and_then(|value| value.to_str()) != Some("ts") {
            continue;
        }
        let Some(filename) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if skip.contains_key(filename) {
            continue;
        }
        // Reading the whole file would be wasteful: a wrong key is rejected by the first four
        // packets, and the file may be large.
        let Ok(mut handle) = std::fs::File::open(&path) else {
            continue;
        };
        let mut head = Vec::with_capacity(PROBE_BYTES);
        if handle.by_ref().take(PROBE_BYTES as u64).read_to_end(&mut head).is_err() {
            continue;
        }
        for candidate in candidates {
            if opens(filename, candidate, &head) {
                out.insert(filename.to_string(), candidate.clone());
                break;
            }
        }
    }
    Ok(out)
}

/// Lesson id used for entries that carry no lesson of their own — an older library, or a segment
/// the API never named. They still decrypt and still merge, just among themselves.
pub const UNKNOWN_LESSON: &str = "unknown";

/// Read a key library from disk.
///
/// A missing file is an empty library rather than an error: the first run has nothing to resume
/// from, and that is an ordinary state, not a failure. The library exists so keys already
/// recovered survive both a player restart and an interrupted sweep.
pub fn load_library(path: &Path) -> Library {
    std::fs::read(path)
        .ok()
        .and_then(|bytes| serde_json::from_slice::<BTreeMap<String, RawEntry>>(&bytes).ok())
        .map(|raw| raw.into_iter().map(|(file, entry)| (file, entry.into())).collect())
        .unwrap_or_default()
}

/// Write the key library, creating the parent directory if needed.
pub fn save_library(path: &Path, library: &Library) -> Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, serde_json::to_vec_pretty(library)?)?;
    Ok(())
}

/// One lesson's segments, ready to decrypt and merge.
pub struct LessonGroup {
    /// Playback index -> (filename, key).
    pub entries: BTreeMap<u32, (String, String)>,
    /// True when every segment here carries a real index read from the player.
    ///
    /// False means the indexes were assigned positionally as a fallback, which says nothing about
    /// playback order. Such a group can still be decrypted, but merging it produces a file of the
    /// wrong length and duration without anything failing — so callers must not merge it. This is
    /// the ordinary state for segments whose URLs the player has already released: keys are never
    /// dropped, URLs are.
    pub placed: bool,
}

/// Split the library into one group per lesson.
///
/// Merging must happen per lesson, never across the whole library: indexes restart at 0 for each
/// lesson, so a global index space would overwrite one lesson's segments with another's.
pub fn group_by_lesson(library: &Library) -> BTreeMap<String, LessonGroup> {
    let mut groups: BTreeMap<String, Vec<(&String, &KeyEntry)>> = BTreeMap::new();
    for (file, entry) in library {
        let lesson = entry.lesson.clone().unwrap_or_else(|| UNKNOWN_LESSON.to_string());
        groups.entry(lesson).or_default().push((file, entry));
    }

    let mut out = BTreeMap::new();
    for (lesson, mut items) in groups {
        items.sort_by(|left, right| left.0.cmp(right.0));
        let placed = items.iter().all(|(_, entry)| entry.index.is_some());
        let mut used: BTreeSet<u32> = items.iter().filter_map(|(_, entry)| entry.index).collect();
        let mut next = 0u32;
        let mut entries = BTreeMap::new();
        for (file, entry) in items {
            let index = match entry.index {
                Some(index) => index,
                None => {
                    while used.contains(&next) {
                        next += 1;
                    }
                    used.insert(next);
                    next
                }
            };
            entries.insert(index, (file.clone(), entry.key.clone()));
        }
        out.insert(lesson, LessonGroup { entries, placed });
    }
    out
}

/// Decrypt the segments `keys` covers, writing `<index:06>.ts` into `out`.
///
/// Reads from the player's cache and never touches the network: the encrypted bytes the player
/// downloaded are exactly what the key opens. Segments that fail to decrypt are skipped, not
/// reported as errors -- a partial file is an ordinary state for a cache being written to.
pub fn decrypt_into(
    cache: &Path,
    out: &Path,
    keys: &BTreeMap<u32, (String, String)>,
) -> Result<usize> {
    std::fs::create_dir_all(out)?;
    let mut written = 0usize;
    for (index, (file, key_text)) in keys {
        let Ok(ciphertext) = std::fs::read(cache.join(file)) else {
            continue;
        };
        let Ok(key) = key_from_text(key_text) else {
            continue;
        };
        let mask = mask_from_filename(file);
        let Ok(plain) = decrypt(&ciphertext, &key, &mask, file) else {
            continue;
        };
        std::fs::write(out.join(format!("{index:06}.ts")), &plain)?;
        written += 1;
    }
    Ok(written)
}

