1	//! The harvest loop.
2	//!
3	//! Shape of a run: poll the player for (index, file, key) and for signed URLs, join the two on
4	//! filename, download and decrypt whatever is new, and repeat until the lesson stops growing.
5	//! Everything already decrypted is on disk, so a rerun resumes.
6	//!
7	//! The loop body is a direct port of the version that completed a 43-minute lesson end to end.
8	//! The borrow structure in the worker pool in particular is deliberately left as it was — it is
9	//! the part most easily broken by a well-meaning rewrite.
10	
11	use super::{fetch, GrabOptions, Harvester, Segment, MAX_SWEEPS, SWEEP_AFTER};
12	use crate::media;
13	use anyhow::Result;
14	use evmedia_contract::{Event, Reporter, SegmentState, Stage, StageState, Status};
15	use std::{
16	    collections::{BTreeMap, BTreeSet, HashMap},
17	    fs,
18	    time::{Duration, Instant},
19	};
20	
21	pub fn run(harvester: &dyn Harvester, options: &GrabOptions, reporter: &Reporter) -> Result<()> {
22	    let enc_dir = options.output.join("enc");
23	    let dec_dir = options.output.join("dec");
24	    fs::create_dir_all(&enc_dir)?;
25	    fs::create_dir_all(&dec_dir)?;
26	
27	    reporter.info(format!(
28	        "attached to EVPlayer2 pid={} (memory scan only, no injection)",
29	        harvester.pid()
30	    ));
31	
32	    let client = reqwest::blocking::Client::builder()
33	        .user_agent("restclient-cpp")
34	        .timeout(Duration::from_secs(60))
35	        .build()?;
36	
37	    let started = Instant::now();
38	    // Resume from anything already decrypted: the merge and the completeness check both work
39	    // off `ok`, so pre-existing files have to be counted or a rerun would throw them away.
40	    let mut ok: BTreeMap<u32, String> = fetch::resume(&dec_dir);
41	    if !ok.is_empty() {
42	        reporter.info(format!("resuming with {} already decrypted segment(s)", ok.len()));
43	    }
44	
45	    let mut failed: HashMap<u32, (usize, String)> = HashMap::new();
46	    let mut idle = 0usize;
47	    let mut last_report = Instant::now();
48	    // Every segment index the player has ever exposed. The live window slides, so without this
49	    // a gap would be invisible the moment the playhead moved on -- and the sweep would have
50	    // nothing to aim at.
51	    let mut seen: BTreeSet<u32> = BTreeSet::new();
52	    let mut sweeps_left = MAX_SWEEPS;
53	    let mut cancelled = false;
54	
55	    reporter.event(&Event::Stage {
56	        name: Stage::Scan,
57	        state: StageState::Begin,
58	        detail: String::new(),
59	    });
60	
61	    loop {
62	        if reporter.stopped() {
63	            reporter.info("stop requested; finishing");
64	            cancelled = true;
65	            break;
66	        }
67	
68	        let keys = harvester.keys()?;
69	        let urls = harvester.urls();
70	        if keys.is_empty() && urls.is_empty() && ok.is_empty() && started.elapsed().as_secs() < 30 {
71	            reporter.info(format!("  nothing visible yet: {}", harvester.diagnose()));
72	        }
73	
74	        let jobs: Vec<Segment> = keys
75	            .iter()
76	            .filter_map(|(index, (file, key))| {
77	                let url = urls.get(file)?;
78	                Some(Segment { index: *index, file: file.clone(), key: key.clone(), url: url.clone() })
79	            })
80	            .collect();
81	
82	        let mut progressed = false;
83	        // Only indexes that joined a signed URL of this lesson count: the player can hold
84	        // contexts from more than one lesson, and a stray index would send the sweep chasing a
85	        // gap that does not belong to the lesson being captured.
86	        seen.extend(jobs.iter().map(|segment| segment.index));
87	
88	        let pending: Vec<&Segment> = jobs
89	            .iter()
90	            .filter(|segment| {
91	                !ok.contains_key(&segment.index)
92	                    && !failed.get(&segment.index).is_some_and(|(n, _)| *n >= options.attempts)
93	            })
94	            .collect();
95	
96	        if !pending.is_empty() {
97	            let mut results: Vec<(u32, String, Result<()>)> = Vec::with_capacity(pending.len());
98	            {
99	                let next = std::sync::atomic::AtomicUsize::new(0);
100	                let sink = std::sync::Mutex::new(&mut results);
101	                std::thread::scope(|scope| {
102	                    for _ in 0..options.jobs.max(1) {
103	                        scope.spawn(|| loop {
104	                            let index = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
105	                            if index >= pending.len() {
106	                                break;
107	                            }
108	                            let segment = pending[index];
109	                            let outcome = fetch::fetch_and_decode(&client, &enc_dir, &dec_dir, segment);
110	                            sink.lock().unwrap().push((
111	                                segment.index,
112	                                segment.file.clone(),
113	                                outcome,
114	                            ));
115	                        });
116	                    }
117	                });
118	            }
119	            for (index, file, outcome) in results {
120	                match outcome {
121	                    Ok(()) => {
122	                        ok.insert(index, file.clone());
123	                        failed.remove(&index);
124	                        progressed = true;
125	                        reporter.event(&Event::Segment {
126	                            index,
127	                            file,
128	                            state: SegmentState::Done,
129	                            attempt: 1,
130	                            error: None,
131	                        });
132	                    }
133	                    Err(error) => {
134	                        let entry = failed.entry(index).or_insert((0, String::new()));
135	                        entry.0 += 1;
136	                        entry.1 = error.to_string();
137	                        reporter.event(&Event::Segment {
138	                            index,
139	                            file,
140	                            state: SegmentState::Failed,
141	                            attempt: entry.0,
142	                            error: Some(entry.1.clone()),
143	                        });
144	                    }
145	                }
146	            }
147	        }
148	        for segment in &jobs {
149	            if !ok.contains_key(&segment.index) && fetch::valid_dec_file(&dec_dir, segment.index) {
150	                ok.insert(segment.index, segment.file.clone());
151	            }
152	        }
153	
154	        if progressed {
155	            idle = 0;
156	        } else {
157	            idle += 1;
158	        }
159	
160	        // The GUI gets a sample every poll; a terminal user still sees the counters only every
161	        // ten seconds, so the cadence they are used to does not change.
162	        reporter.event(&Event::Progress {
163	            stage: Stage::Scan,
164	            keys: keys.len(),
165	            urls: urls.len(),
166	            segments: jobs.len(),
167	            done: ok.len(),
168	            failed: failed.len(),
169	            elapsed_secs: started.elapsed().as_secs(),
170	        });
171	        if last_report.elapsed() > Duration::from_secs(10) {
172	            last_report = Instant::now();
173	            reporter.info(format!(
174	                "  keys={:<5} urls={:<5} segments={:<5} done={:<5} failed={:<4} elapsed={}s",
175	                keys.len(),
176	                urls.len(),
177	                jobs.len(),
178	                ok.len(),
179	                failed.len(),
180	                started.elapsed().as_secs()
181	            ));
182	        }
183	
184	        // The visible segment set grows as the lesson plays, so "everything known is done" is
185	        // not the same as "the lesson is complete"; keep polling and let the idle limit or the
186	        // stop signal end the run.
187	        let known: Vec<u32> = jobs.iter().map(|segment| segment.index).collect();
188	        if !known.is_empty() && known.iter().all(|index| ok.contains_key(index)) && idle == 0 {
189	            reporter.info("  caught up with the player; keep playing to reveal more segments");
190	        }
191	
192	        // Waiting cannot fill a gap the playhead already ran past -- those keys were never
193	        // computed. Walk the playhead back to the earliest one and let it decrypt again.
194	        let gap = seen.iter().find(|index| !ok.contains_key(index)).copied();
195	        if options.sweep && sweeps_left > 0 && idle >= SWEEP_AFTER {
196	            if let Some(target) = gap {
197	                reporter.info(format!(
198	                    "  stalled {idle} poll(s) with a gap behind the playhead; sweeping back to index {target}"
199	                ));
200	                sweeps_left -= 1;
201	                match harvester.seek_to(target, options.press_gap, reporter) {
202	                    Ok(true) => {
203	                        reporter.info("  playhead is inside the gap; letting the player re-decrypt");
204	                        idle = 0;
205	                        reporter.sleep(options.poll);
206	                        continue;
207	                    }
208	                    Ok(false) => {
209	                        // Seek keys are not bound in this build: stop trying, stay a passive
210	                        // observer rather than hammering the player.
211	                        reporter.info("  sweep unavailable; waiting for manual playback instead");
212	                        sweeps_left = 0;
213	                    }
214	                    Err(error) => reporter.info(format!("  sweep failed: {error}")),
215	                }
216	            }
217	        }
218	
219	        if idle >= options.idle_limit {
220	            reporter.info(format!("no progress for {idle} polls; stopping"));
221	            break;
222	        }
223	        reporter.sleep(options.poll);
224	    }
225	
226	    reporter.event(&Event::Stage {
227	        name: Stage::Scan,
228	        state: StageState::End,
229	        detail: String::new(),
230	    });
231	
232	    finish(&dec_dir, options, &ok, cancelled, reporter)
233	}
234	
235	fn finish(
236	    dec_dir: &std::path::Path,
237	    options: &GrabOptions,
238	    ok: &BTreeMap<u32, String>,
239	    cancelled: bool,
240	    reporter: &Reporter,
241	) -> Result<()> {
242	    if ok.is_empty() {
243	        reporter.info("nothing decrypted yet; keep the lesson playing and rerun");
244	        reporter.event(&Event::Finished {
245	            status: Status::Nothing,
246	            exit_code: evmedia_contract::exit::OK,
247	            message: String::new(),
248	        });
249	        return Ok(());
250	    }
251	
252	    let indexes: Vec<u32> = ok.keys().copied().collect();
253	    let outcome = media::merge_lesson(dec_dir, &options.output, &indexes, reporter)?;
254	
255	    let status = if cancelled {
256	        Status::Cancelled
257	    } else if outcome.complete {
258	        Status::Complete
259	    } else {
260	        Status::Partial
261	    };
262	
263	    if options.mp4 && outcome.complete {
264	        reporter.event(&Event::Stage {
265	            name: Stage::Remux,
266	            state: StageState::Begin,
267	            detail: String::new(),
268	        });
269	        let mp4 = options.output.join("lesson.mp4");
270	        media::remux_mp4(&outcome.path, &mp4, reporter)?;
271	        reporter.event(&Event::Stage {
272	            name: Stage::Remux,
273	            state: StageState::End,
274	            detail: String::new(),
275	        });
276	    } else if options.mp4 {
277	        reporter.info(
278	            "refusing to remux an incomplete merge; play the rest and rerun (segments are cached)",
279	        );
280	    }
281	
282	    reporter.event(&Event::Finished {
283	        status,
284	        exit_code: evmedia_contract::exit::OK,
285	        message: format!("merged {} segment(s)", outcome.count),
286	    });
287	    Ok(())
288	}
