1	//! Driving the player's playhead without touching its UI.
2	//!
3	//! A segment the playhead never reached has no key anywhere: the AES schedule only exists once
4	//! the player decrypts that segment for playback, and nothing in the download path computes it.
5	//! So a gap left behind the playhead can only be filled by putting the playhead back inside the
6	//! gap and letting the read-ahead decrypt it again.
7	//!
8	//! Posting `WM_KEYDOWN`/`WM_KEYUP` to the player's own window does that without focus, without
9	//! injection, and without knowing a single UI coordinate — only the window handle is needed.
10	//! The live key window doubles as a position readout: it starts at the playhead and runs some
11	//! way ahead of it, so the sweep can measure how far one key press moved things and size the
12	//! next batch from that rather than assuming a step size.
13	
14	use crate::process::Player;
15	use anyhow::Result;
16	use evmedia_contract::Reporter;
17	use std::time::Duration;
18	use windows_sys::Win32::{
19	    Foundation::RECT,
20	    UI::WindowsAndMessaging::{
21	        EnumWindows, GetWindowRect, GetWindowThreadProcessId, IsWindowVisible, PostMessageW,
22	        WM_KEYDOWN, WM_KEYUP,
23	    },
24	};
25	
26	const VK_LEFT: usize = 0x25;
27	const VK_RIGHT: usize = 0x27;
28	
29	/// The key that steps the playhead forward by one increment.
30	pub const STEP_FORWARD: usize = VK_RIGHT;
31	
32	/// Post `count` presses of `vk` to the player's window, returning how many were sent.
33	///
34	/// Zero means the player has no visible window to post to, which is the caller's cue to stop
35	/// rather than loop. Used by the key sweep, which walks the playhead across a whole lesson so the
36	/// player decrypts every segment along the way.
37	pub fn press(player: &Player, vk: usize, count: usize, gap: Duration) -> usize {
38	    let Some(hwnd) = player_window(player.pid()) else {
39	        return 0;
40	    };
41	    post_key(hwnd, vk, count, gap);
42	    count
43	}
44	
45	struct WindowPick {
46	    pid: u32,
47	    best: isize,
48	    area: i64,
49	}
50	
51	unsafe extern "system" fn pick_window(hwnd: isize, lparam: isize) -> i32 {
52	    let pick = &mut *(lparam as *mut WindowPick);
53	    if IsWindowVisible(hwnd) == 0 {
54	        return 1;
55	    }
56	    let mut owner = 0u32;
57	    GetWindowThreadProcessId(hwnd, &mut owner);
58	    if owner != pick.pid {
59	        return 1;
60	    }
61	    let mut rect: RECT = std::mem::zeroed();
62	    if GetWindowRect(hwnd, &mut rect) == 0 {
63	        return 1;
64	    }
65	    let area = (rect.right - rect.left) as i64 * (rect.bottom - rect.top) as i64;
66	    if area > pick.area {
67	        pick.area = area;
68	        pick.best = hwnd;
69	    }
70	    1
71	}
72	
73	/// The player's largest visible top-level window; posted input goes here.
74	pub fn player_window(pid: u32) -> Option<isize> {
75	    let mut pick = WindowPick { pid, best: 0, area: 0 };
76	    unsafe { EnumWindows(Some(pick_window), &mut pick as *mut _ as isize) };
77	    (pick.best != 0).then_some(pick.best)
78	}
79	
80	fn post_key(hwnd: isize, vk: usize, count: usize, gap: Duration) {
81	    for _ in 0..count {
82	        unsafe {
83	            PostMessageW(hwnd, WM_KEYDOWN, vk, 0);
84	            PostMessageW(hwnd, WM_KEYUP, vk, 0);
85	        }
86	        std::thread::sleep(gap);
87	    }
88	}
89	
90	/// Move the playhead so that `target` sits inside the live (decrypted) key window, which is
91	/// what makes the player decrypt it. Returns false when the seek keys turn out to be unbound,
92	/// so the caller can stop asking instead of looping forever.
93	pub fn seek_window_to(
94	    player: &Player,
95	    target: u32,
96	    press_gap: Duration,
97	    reporter: &Reporter,
98	) -> Result<bool> {
99	    let Some(hwnd) = player_window(player.pid()) else {
100	        reporter.info(format!("  no visible player window for pid {}; cannot sweep", player.pid()));
101	        return Ok(false);
102	    };
103	    // Segments moved per key press. The first batch guesses 1 and the measurement corrects it.
104	    let mut per_press = 1.0f64;
105	    for round in 1..=8 {
106	        let live = player.active_keys();
107	        let (Some(&current), Some(&highest)) = (live.keys().next(), live.keys().next_back()) else {
