1	//! Segment key material, in one place.
2	//!
3	//! There are two ways a key reaches us and they must not be confused, because getting it wrong
4	//! produces a 16-byte "key" and a total failure with no useful error:
5	//!
6	//! * the **live** path (`grab`) reads a 32-byte AES schedule out of the player and turns it into
7	//!   a 32-character lowercase hex *string*, which is then used **directly as 32 key bytes** —
8	//!   see [`key_from_text`].
9	//! * the **manifest** path (`decode-ev`) stores that same string already hex-encoded, so it is
10	//!   64 characters that must be **decoded** back to 32 bytes — see [`key_from_hex`].
11	//!
12	//! [`decrypt`] therefore takes the finished `[u8; 32]` and `[u8; 16]`, and each caller picks
13	//! the constructor that matches where its key came from.
14	
15	use aes::Aes256;
16	use anyhow::{bail, Context, Result};
17	use ecb::cipher::{block_padding::NoPadding, BlockDecryptMut, KeyInit};
18	use md5::{Digest as _, Md5};
19	use sha2::Sha256;
20	
21	/// First four bytes of a context's key schedule before the player has decrypted that segment
22	/// (`0xBAADF00D` in little-endian). A schedule starting with this is not a key yet.
23	pub const HEAP_FILL: [u8; 4] = [0x0d, 0xf0, 0xad, 0xba];
24	
25	fn xtime(value: u8) -> u8 {
26	    (value << 1) ^ if value & 0x80 != 0 { 0x1b } else { 0 }
27	}
28	
29	/// Inverse of the MixColumns step the player applies to the second half of the schedule.
30	fn mix(input: &[u8]) -> [u8; 16] {
31	    let mut output = [0u8; 16];
32	    for base in (0..16).step_by(4) {
33	        let t = input[base] ^ input[base + 1] ^ input[base + 2] ^ input[base + 3];
34	        for index in 0..4 {
35	            output[base + index] =
36	                input[base + index] ^ t ^ xtime(input[base + index] ^ input[base + (index + 1) % 4]);
37	        }
38	    }
39	    output
40	}
41	
42	/// Rebuild the 32-character hex key from a playback context's 32-byte schedule.
43	///
44	/// The player keeps `key[0..16]` verbatim and `key[16..32]` MixColumns'd. Returns `None` while
45	/// the slot is still heap fill or zeroed, which is how "the player has not decrypted this
46	/// segment yet" is detected.
47	pub fn schedule_to_key(schedule: &[u8; 32]) -> Option<String> {
48	    if schedule[..4] == HEAP_FILL || schedule.iter().all(|byte| *byte == 0) {
49	        return None;
50	    }
51	    let mut key = [0u8; 32];
52	    key[..16].copy_from_slice(&schedule[..16]);
53	    key[16..].copy_from_slice(&mix(&schedule[16..]));
54	    let text = String::from_utf8(key.to_vec()).ok()?;
55	    is_hex32(&text).then_some(text)
56	}
57	
58	/// Key as it exists in the live path: 32 hex characters used directly as 32 bytes.
