1	//! Raw access to another process's memory.
2	//!
3	//! Nothing here knows about EVPlayer2: it is a read handle, a region walker, and the decoder
4	//! for the string fields the playback contexts use. The constants below describe the context
5	//! object layout and belong with the code that reads it.
6	
7	use anyhow::{bail, Result};
8	use std::ffi::c_void;
9	use windows_sys::Win32::{
10	    Foundation::{CloseHandle, HANDLE, INVALID_HANDLE_VALUE},
11	    System::{
12	        Diagnostics::{
13	            Debug::ReadProcessMemory,
14	            ToolHelp::{
15	                CreateToolhelp32Snapshot, Process32FirstW, Process32NextW, PROCESSENTRY32W,
16	                TH32CS_SNAPPROCESS,
17	            },
18	        },
19	        Memory::{
20	            VirtualQueryEx, MEMORY_BASIC_INFORMATION, MEM_COMMIT, MEM_IMAGE, PAGE_EXECUTE_READ,
21	            PAGE_EXECUTE_READWRITE, PAGE_EXECUTE_WRITECOPY, PAGE_GUARD, PAGE_NOACCESS,
22	            PAGE_READONLY, PAGE_READWRITE, PAGE_WRITECOPY,
23	        },
24	        Threading::{OpenProcess, PROCESS_QUERY_INFORMATION, PROCESS_VM_READ},
25	    },
26	};
27	
28	/// The player's image name, as the process list spells it.
29	const PLAYER_IMAGE: &str = "EVPlayer2.exe";
30	
31	/// The pid of the running EVPlayer2, if there is one.
32	///
33	/// This is the only step here that is about EVPlayer2 rather than about reading memory, and it
34	/// exists so no caller has to find the pid by hand. When several copies are running the first
35	/// one the snapshot yields wins; pass `--pid` to be specific.
36	pub fn find_player_pid() -> Option<u32> {
37	    unsafe {
38	        let snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
39	        if snapshot == INVALID_HANDLE_VALUE {
40	            return None;
41	        }
42	        let mut entry: PROCESSENTRY32W = std::mem::zeroed();
43	        entry.dwSize = std::mem::size_of::<PROCESSENTRY32W>() as u32;
44	        let mut found = None;
45	        if Process32FirstW(snapshot, &mut entry) != 0 {
46	            loop {
47	                let end = entry.szExeFile.iter().position(|unit| *unit == 0).unwrap_or(0);
48	                let name = String::from_utf16_lossy(&entry.szExeFile[..end]);
49	                if name.eq_ignore_ascii_case(PLAYER_IMAGE) {
50	                    found = Some(entry.th32ProcessID);
51	                    break;
52	                }
53	                if Process32NextW(snapshot, &mut entry) == 0 {
54	                    break;
55	                }
56	            }
57	        }
58	        CloseHandle(snapshot);
59	        found
60	    }
61	}
62	
63	/// Size of one playback-context object, and the offsets the scan reads out of it.
64	pub const CONTEXT_SIZE: usize = 0x2a8;
65	/// Segment index within the lesson (`u32`).
66	pub const OFF_INDEX: usize = 8;
67	/// Segment filename.
68	pub const OFF_FILE: usize = 0x18;
69	/// 32-byte AES key schedule, filled in only once the player has decrypted that segment.
70	pub const OFF_SCHEDULE: usize = 0x120;
71	/// The 32-hex-character mask string.
72	pub const OFF_MASK: usize = 0x268;
73	
74	/// Owns the process handle and closes it on drop.
75	struct Process(HANDLE);
76	
77	impl Drop for Process {
78	    fn drop(&mut self) {
79	        unsafe { CloseHandle(self.0) };
80	    }
81	}
82	
83	/// A live handle onto the player, opened once and reused for every poll.
84	pub struct Player {
85	    process: Process,
86	    pub(crate) pid: u32,
87	}
88	
89	impl Player {
90	    pub fn open(pid: u32) -> Result<Self> {
91	        let handle = unsafe { OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, 0, pid) };
92	        if handle == 0 {
93	            bail!("cannot read process {pid}; run as the same user or with sufficient rights");
