//! `capture-ev`: write a manifest for a lesson from a live player.
//!
//! Keys are recovered the same way the harvest loop recovers them: by testing the 32-hex
//! candidates the player holds against each segment's own encrypted bytes. This replaces an
//! earlier collector whose only key source was a salt-based derivation that this build turned
//! out not to implement — it searched process memory for `tk + filename` and never found it, so
//! that command could only ever fail. See `docs/ARCHITECTURE.md`.
//!
//! PRECONDITION: every segment in `input` must have been decrypted by the player at least once,
//! which means the lesson has been played through. This is a consequence of where keys come
//! from, not a limitation that can be coded around here.

use crate::process::Player;
use anyhow::{bail, Context, Result};
use evmedia_contract::Reporter;
use evmedia_core::{
    crypto::{hex_lower, mask_from_filename, sha256_hex},
    decode::{find_input_bytes, list_input_names, CaptureManifest, EvSegment},
    keyscan::{self, Library},
};
use std::path::Path;

const TOOL: &str = "EVPlayer2 5.0.5 Rust live collector";

pub fn capture(pid: u32, input: &Path, output: &Path, reporter: &Reporter) -> Result<()> {
    let names: Vec<String> = list_input_names(input)?
        .into_iter()
        .filter(|name| name.ends_with(".ts"))
        .collect();
    if names.is_empty() {
        bail!("input holds no .ts segments");
    }

    let player = Player::open(pid)?;
    // The key comes out of the segment's bytes, so the input directory is what it is recovered
    // from. Nothing is read from a struct field: the context object's key-schedule slot never
    // held a key, and the previous version of this command failed on every run because of it.
    let candidates = player.hex_candidates();
    let by_file = keyscan::recover(input, &candidates, &Library::new())?;
    // The index, unlike the key, is not in the segment: it is only in the player's context
    // objects, and it decides the order `decode-ev` reassembles in.
    let indexes = player.segment_indexes();

    let mut missing = Vec::new();
    let mut found: Vec<(u32, String, String)> = Vec::new();
    for name in &names {
        match (by_file.get(name), indexes.get(name)) {
            (Some(key), Some(index)) => found.push((*index, name.clone(), key.clone())),
            _ => missing.push(name.clone()),
        }
    }
    if !missing.is_empty() {
        bail!(
            "no key and index for {} of {} segment(s); the player derives a key only while it \
             plays a segment, so play the lesson through and retry. First missing: {}",
            missing.len(),
            names.len(),
            missing[0]
        );
    }
    found.sort_by_key(|(index, _, _)| *index);

