/// The indexes whose segment the player has already decrypted for playback.
///
/// This reads the key-schedule slot for exactly one bit — filled or not — and uses it as a
/// **position** signal: it says where the playhead has been, which is what a seek needs in
/// order to aim. It is not a key source, and nothing here turns the slot into a key; every
/// key that has actually opened a segment came from testing a candidate against that
/// segment's bytes.
///
/// [`Player::segment_indexes`] is the wrong instrument for this even though both walk the
/// same objects. It reports every context the player holds, decrypted or not, and on a real
/// lesson that is the whole lesson — a recorded dump of a live player in
/// `tools/parser-tools/dump_contexts.json` shows 134 contexts held with only 2 decrypted.
/// Measuring a "live window" from it spans the entire lesson, so a seek is always told it
/// has already arrived and never moves.
pub fn decrypted_indexes(&self) -> BTreeSet<u32> {
    let Some(base) = self.module_base(RENDER_DLL) else {
        return BTreeSet::new();
    };
    let (low, high) = (base + VTABLE_LOW, base + VTABLE_HIGH);
    let mut out = BTreeSet::new();
    self.for_each_chunk(4 << 20, |chunk_base, bytes| {
        for offset in (0..bytes.len().saturating_sub(8)).step_by(8) {
            let pointer =
                u64::from_le_bytes(bytes[offset..offset + 8].try_into().unwrap()) as usize;
            if pointer < low || pointer >= high {
                continue;
            }
            let Some(object) = self.read(chunk_base + offset, CONTEXT_SIZE) else { continue };
            let Some(file) = self.string_field(&object, OFF_FILE) else { continue };
            if !file.ends_with(".ts") {
                continue;
            }
            let schedule = &object[OFF_SCHEDULE..OFF_SCHEDULE + 32];
            if schedule[..4] == HEAP_FILL || schedule.iter().all(|byte| *byte == 0) {
                continue;
            }
            let index = u32::from_le_bytes(object[OFF_INDEX..OFF_INDEX + 4].try_into().unwrap());
            out.insert(index);
        }
    });
    out
}

/// Segment filename -> lesson id, from the signed URLs the player built for its own requests.

