/// The lowest and highest segment index the player is currently holding a context for.
///
/// This is the window the sweep aims at, and it doubles as the position readout the caller
/// measures a key press with. It is read from the context objects' index field — the same one
/// the index scan uses — and deliberately *not* from their key-schedule slot. That slot was used
/// here for a long time and is always empty, which made this function report "the player is not
/// holding a key window" on every call and quietly turned the sweep into a no-op.
fn live_window(player: &Player) -> Option<(u32, u32)> {
    let indexes = player.segment_indexes();
    let low = indexes.values().copied().min()?;
    let high = indexes.values().copied().max()?;
    Some((low, high))
}

input.new_string:
/// The lowest and highest segment index the player has already decrypted.
///
/// This is the window the sweep aims at, and it doubles as the position readout the caller
/// measures a key press with — a press moves this window, which is the only feedback available
/// without reading the player's UI.
///
/// It must be the *decrypted* set, not every context the player holds. The player holds a
/// context for each segment it has touched, which on a real lesson is the whole lesson; a window
/// measured from those spans everything, so `seek_window_to`'s "is the target already inside?"
/// guard is satisfied for a segment that was never decrypted and the seek posts no keys at all
/// while reporting success. See `Player::decrypted_indexes`.
fn live_window(player: &Player) -> Option<(u32, u32)> {
    let decrypted = player.decrypted_indexes();
    Some((*decrypted.first()?, *decrypted.last()?))
}

