                object[OFF_SCHEDULE..OFF_SCHEDULE + 32].try_into().unwrap();
            let Some(key) = schedule_to_key(&schedule) else { continue };
            let index = u32::from_le_bytes(object[OFF_INDEX..OFF_INDEX + 4].try_into().unwrap());
            out.insert(index, (file, key));
