1	//! `capture-ev`: write a manifest for a lesson from a live player.
2	//!
3	//! Keys are recovered the same way the harvest loop recovers them: by testing the 32-hex
4	//! candidates the player holds against each segment's own encrypted bytes. This replaces an
5	//! earlier collector whose only key source was a salt-based derivation that this build turned
6	//! out not to implement — it searched process memory for `tk + filename` and never found it, so
7	//! that command could only ever fail. See `docs/ARCHITECTURE.md`.
8	//!
9	//! PRECONDITION: every segment in `input` must have been decrypted by the player at least once,
10	//! which means the lesson has been played through. This is a consequence of where keys come
11	//! from, not a limitation that can be coded around here.
12	
13	use crate::process::Player;
14	use anyhow::{bail, Context, Result};
15	use evmedia_contract::Reporter;
16	use evmedia_core::{
17	    crypto::{hex_lower, mask_from_filename, sha256_hex},
18	    decode::{find_input_bytes, list_input_names, CaptureManifest, EvSegment},
19	    keyscan::{self, Library},
20	};
21	use std::path::Path;
22	
23	const TOOL: &str = "EVPlayer2 5.0.5 Rust live collector";
24	
25	pub fn capture(pid: u32, input: &Path, output: &Path, reporter: &Reporter) -> Result<()> {
26	    let names: Vec<String> = list_input_names(input)?
27	        .into_iter()
28	        .filter(|name| name.ends_with(".ts"))
29	        .collect();
30	    if names.is_empty() {
31	        bail!("input holds no .ts segments");
32	    }
