export const meta = {
  name: 'session-review',
  description: 'Read the full session transcript and produce a complete done / not-done inventory',
  phases: [
    { title: 'Extract', detail: 'eight readers over disjoint line ranges of the digest' },
    { title: 'Merge', detail: 'dedupe into one inventory' },
    { title: 'Critic', detail: 'what did the readers miss' },
  ],
}

const DIGEST = 'C:/Users/Yonjay/AppData/Local/Temp/digest.txt'
const TOTAL = 5275
const CHUNKS = 8
const SIZE = Math.ceil(TOTAL / CHUNKS)

const FORMAT = `
The digest is a plain-text narrative of one long Claude Code session, reconstructed from its
transcript. Every line starts with a UTC timestamp and one of:

  [HH:MM:SS] USER: ...              a message the human user sent
  [HH:MM:SS] CLAUDE: ...            a message Claude wrote to the user
  [HH:MM:SS]   -> Tool: detail      a tool call (Bash, Write, Edit, Read, Task, Workflow, ...)

The timestamps are UTC; the user is at UTC+8, so 04:15 UTC is 12:15 local.

The project is "ev-reverse": reverse-engineering a Chinese video player (EVPlayer2) to recover
the per-segment AES keys for its encrypted video cache and decrypt the lessons. The user speaks
Chinese and is impatient; Claude replies in Chinese.

Read ONLY your assigned line range with the Read tool, using offset and limit exactly as given.
Do not read the rest of the file. Your range is a slice of one continuous session, so it will
often begin or end mid-topic -- report what is in it regardless.
`

const CHUNK_SCHEMA = {
  type: 'object',
  properties: {
    user_requests: {
      type: 'array',
      description: 'Every distinct thing the user asked for in this range, in their own terms.',
      items: { type: 'string' },
    },
    completed: {
      type: 'array',
      description: 'Work that was actually carried out and evidenced in this range.',
      items: {
        type: 'object',
        properties: {
          item: { type: 'string', description: 'the concrete change or result' },
          evidence: { type: 'string', description: 'how you can tell it happened: a commit, a test, a command output, a file written' },
        },
        required: ['item', 'evidence'],
      },
    },
    attempted_failed: {
      type: 'array',
      description: 'Things that were tried and did NOT work, or were abandoned.',
      items: {
        type: 'object',
        properties: {
          item: { type: 'string' },
          outcome: { type: 'string', description: 'why it failed or was dropped' },
        },
        required: ['item', 'outcome'],
      },
    },
    claimed_open: {
      type: 'array',
      description: 'Things Claude explicitly said were still to do, or not yet verified.',
      items: { type: 'string' },
    },
    corrections: {
      type: 'array',
      description: 'Claims made earlier in the session that were later found to be wrong, and what replaced them.',
      items: { type: 'string' },
    },
  },
  required: ['user_requests', 'completed', 'attempted_failed', 'claimed_open', 'corrections'],
}

const ranges = []
for (let index = 0; index < CHUNKS; index++) {
  const offset = index * SIZE + 1
  const limit = Math.min(SIZE, TOTAL - index * SIZE)
  if (limit > 0) ranges.push({ index, offset, limit })
}

phase('Extract')
const chunks = await parallel(
  ranges.map((range) => () =>
    agent(
      `${FORMAT}

Read lines ${range.offset} to ${range.offset + range.limit - 1} of ${DIGEST}
(Read with offset: ${range.offset}, limit: ${range.limit}).

Extract everything that happened in that range. Be exhaustive and concrete: name the file, the
command, the number, the commit. Vague entries like "improved the code" are useless. Include
failed attempts -- they matter as much as successes, because the user is asking what was NOT done.
For user_requests, use the user's own words where they are short enough to quote.`,
      { label: `read:${range.offset}`, phase: 'Extract', schema: CHUNK_SCHEMA },
    ),
  ),
)

const good = chunks.filter(Boolean)
log(`${good.length} of ${ranges.length} ranges read`)

const inbox = JSON.stringify(good, null, 1)

phase('Merge')
const merged = await agent(
  `You are given the structured findings of ${good.length} readers who each covered one slice of
ONE continuous session transcript. Merge them into a single inventory.

Rules:
- This is one continuous session, so the same topic often spans readers. Deduplicate, but keep
  every distinct fact; do not lose detail to make the merge tidy.
- Preserve concrete specifics: file paths, commit hashes, test counts, measured numbers, command
  names. Strip nothing that a reader called evidence.
- Order the work roughly chronologically. The readers' slices are already in order.
- A request the user made must be classified as DONE, PARTIAL, or NOT DONE, based only on what the
  readers found. If no reader recorded evidence that it was finished, classify it PARTIAL or NOT
  DONE and say what is missing -- do not assume it was done because it was asked for.

The readers' findings:
${inbox}`,
  {
    label: 'merge',
    phase: 'Merge',
    schema: {
      type: 'object',
      properties: {
        requests: {
          type: 'array',
          description: 'Everything the user asked for across the session, with its verdict.',
          items: {
            type: 'object',
            properties: {
              request: { type: 'string' },
              status: { type: 'string', enum: ['DONE', 'PARTIAL', 'NOT DONE'] },
              detail: { type: 'string', description: 'what was actually delivered, with specifics' },
            },
            required: ['request', 'status', 'detail'],
          },
        },
        delivered: {
          type: 'array',
          description: 'Concrete artifacts produced, with specifics.',
          items: {
            type: 'object',
            properties: {
              item: { type: 'string' },
              detail: { type: 'string' },
            },
            required: ['item', 'detail'],
          },
        },
        not_done: {
          type: 'array',
          description: 'Everything still outstanding at the end of the session.',
          items: {
            type: 'object',
            properties: {
              item: { type: 'string' },
              why: { type: 'string', description: 'blocked, abandoned, never started, or awaiting the user' },
            },
            required: ['item', 'why'],
          },
        },
        corrections: {
          type: 'array',
          description: 'Claims made during the session that were later found wrong.',
          items: { type: 'string' },
        },
      },
      required: ['requests', 'delivered', 'not_done', 'corrections'],
    },
  },
)

phase('Critic')
const critique = await agent(
  `Below is one merged inventory of a long reverse-engineering session, built by readers who each
saw one slice of the transcript. Your job is to find what the inventory got WRONG or LEFT OUT.

Look specifically for:
- A user request that appears in the transcript but not in the inventory.
- A "DONE" that the evidence does not support.
- A "NOT DONE" that was in fact finished later in the session (readers of later slices would have
  seen it; the merge may have missed it).
- Anything the assistant promised to do later in the session and never returned to.

The session's transcript digest is at ${DIGEST} (lines 1..${TOTAL}). Spot-check it by reading a few
ranges of your choosing -- especially the very end, since promises are most often left dangling
there. Be concrete: name the request and where in the digest you saw it.

The inventory:
${JSON.stringify(merged, null, 1)}`,
  { label: 'completeness-critic', phase: 'Critic' },
)

return { merged, critique }

