//! The harvest loop.
//!
//! Shape of a run: poll the player for its live keys, its segment indexes and its signed URLs;
//! download the ciphertext those URLs point at; add the keys that are only loose in the heap by
//! testing candidates against that ciphertext; then decrypt and merge whatever is new. Repeat
//! until the lesson stops growing. Everything already decrypted is on disk, so a rerun resumes.
//!
//! Keys arrive from two places and the loop uses both. The player's live playback contexts carry
//! index, filename and key together — cheap and exact — but only while the player still holds
//! that context. A key outlives its context, and after that it is a loose 32-hex string on the
//! heap, which `keyscan` finds by testing candidates against segment bytes.
//!
//! One ordering rule follows, and it is easy to state too strongly: **the download must never be
//! gated on already holding a key.** Gating it is circular — no bytes, no key; no key, no fetch.
//! The version before this asked the player for keys first and then fetched only the segments it
//! already had keys for, so a segment whose key had not arrived yet was never downloaded at all.

use super::{fetch, seek, GrabOptions, Harvester, Segment, MAX_SWEEPS, SWEEP_AFTER};
use crate::{keyscan, keyscan::KeyEntry, keyscan::Library, media};
use anyhow::Result;
use evmedia_contract::{Event, Reporter, SegmentState, Stage, StageState, Status};
use std::{
    collections::{BTreeMap, BTreeSet, HashMap},
    fs,
    time::{Duration, Instant},
};

pub fn run(harvester: &dyn Harvester, options: &GrabOptions, reporter: &Reporter) -> Result<()> {
    let enc_dir = options.output.join("enc");
    let dec_dir = options.output.join("dec");
    fs::create_dir_all(&enc_dir)?;
    fs::create_dir_all(&dec_dir)?;

    reporter.info(format!(
        "attached to EVPlayer2 pid={} (memory scan only, no injection)",
        harvester.pid()
    ));

    let client = reqwest::blocking::Client::builder()
        .user_agent("restclient-cpp")
        .timeout(Duration::from_secs(60))
        .build()?;

    let started = Instant::now();
    // Resume from anything already decrypted: the merge and the completeness check both work
    // off `ok`, so pre-existing files have to be counted or a rerun would throw them away.
    let mut ok: BTreeMap<u32, String> = fetch::resume(&dec_dir);
    if !ok.is_empty() {
        reporter.info(format!("resuming with {} already decrypted segment(s)", ok.len()));
    }

    let mut failed: HashMap<u32, (usize, String)> = HashMap::new();
    let mut idle = 0usize;
    let mut last_report = Instant::now();
    // Every segment index the player has ever exposed. The live window slides, so without this
    // a gap would be invisible the moment the playhead moved on -- and the sweep would have
    // nothing to aim at.
    let mut seen: BTreeSet<u32> = BTreeSet::new();
    let mut sweeps_left = MAX_SWEEPS;
    let mut cancelled = false;
    // Filename -> key, accumulating across polls. A segment solved on an earlier poll is handed
    // back as the skip set so it is not re-derived, which means this poll's `recover` returns
    // only what is new — the accumulated result has to live here or it would be lost.
    let mut known: BTreeMap<String, String> = BTreeMap::new();
    // Filename -> playback index, also sticky. The player releases contexts as playback moves
    // on, so an index read once has to outlive the object it was read from, or a segment already
    // downloaded could never be placed afterwards.
    let mut places: HashMap<String, u32> = HashMap::new();

    reporter.event(&Event::Stage {
        name: Stage::Scan,
        state: StageState::Begin,
        detail: String::new(),
    });

    loop {
        if reporter.stopped() {
            reporter.info("stop requested; finishing");
            cancelled = true;
            break;
        }

        let urls = harvester.urls();
        places.extend(harvester.indexes());
        // The live contexts come first: index, filename and key arrive together, so this is both
        // the cheapest source and the most precise. `keyscan` below covers what it cannot reach —
        // a key whose context the player has already released is only a loose 32-hex string.
        for (index, (file, key)) in harvester.keys() {
            places.insert(file.clone(), index);
            known.insert(file, key);
        }
        // Ciphertext first, keys second — though the order of these two lines is not what
        // carries the weight. What carries it is that the download is never gated on already
        // holding a key, which is circular. Segments already decrypted are left out of the
        // download entirely: on a resumed run that is most of the lesson.
        let done: BTreeSet<String> = places
            .iter()
            .filter(|(_, index)| ok.contains_key(index))
            .map(|(file, _)| file.clone())
            .collect();
        let (fetched, unreachable) = fetch::download_missing(&client, &enc_dir, &urls, &done);

        let skip: Library = known
            .keys()
            .map(|file| (file.clone(), KeyEntry { key: String::new(), index: None, lesson: None }))
            .collect();
        let candidates = harvester.candidates();
        known.extend(keyscan::recover(&enc_dir, &candidates, &skip)?);

        // A key and an index are enough to place and decrypt a cached segment; the URL is only
        // consulted when the ciphertext is missing, so it is carried, not required.
        let jobs: Vec<Segment> = known
            .iter()
            .filter_map(|(file, key)| {
                let index = places.get(file)?;
                Some(Segment {
                    index: *index,
                    file: file.clone(),
                    key: key.clone(),
                    url: urls.get(file).cloned(),
                })
            })
            .collect();

        if jobs.is_empty() && urls.is_empty() && ok.is_empty() && started.elapsed().as_secs() < 30 {
            reporter.info(format!("  nothing visible yet: {}", harvester.diagnose()));
        }

        let mut progressed = false;
        // Every index the player has revealed that this lesson owns. It has to come from `places`
        // and not only from `jobs`: a segment the playhead skipped never gets a key, so it never
        // becomes a job — and a gap the loop cannot see is a gap `--sweep` cannot aim at, which
        // is precisely the case the sweep exists for.
        seen.extend(
            places
                .iter()
                .filter(|(file, _)| urls.contains_key(*file))
                .map(|(_, index)| *index),
        );
        // Only indexes that joined a signed URL of this lesson count: the player can hold
        // contexts from more than one lesson, and a stray index would send the sweep chasing a
        // gap that does not belong to the lesson being captured.
        seen.extend(jobs.iter().map(|segment| segment.index));

        let pending: Vec<&Segment> = jobs
            .iter()
            .filter(|segment| {
                !ok.contains_key(&segment.index)
                    && !failed.get(&segment.index).is_some_and(|(n, _)| *n >= options.attempts)
            })
            .collect();

        if !pending.is_empty() {
            let mut results: Vec<(u32, String, Result<()>)> = Vec::with_capacity(pending.len());
            {
                let next = std::sync::atomic::AtomicUsize::new(0);
                let sink = std::sync::Mutex::new(&mut results);
                std::thread::scope(|scope| {
                    for _ in 0..options.jobs.max(1) {
                        scope.spawn(|| loop {
                            let index = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                            if index >= pending.len() {
                                break;
                            }
                            let segment = pending[index];
                            let outcome = fetch::fetch_and_decode(&client, &enc_dir, &dec_dir, segment);
                            sink.lock().unwrap().push((
                                segment.index,
                                segment.file.clone(),
                                outcome,
                            ));
                        });
                    }
                });
            }
            for (index, file, outcome) in results {
                match outcome {
                    Ok(()) => {
                        ok.insert(index, file.clone());
                        failed.remove(&index);
                        progressed = true;
                        reporter.event(&Event::Segment {
                            index,
                            file,
                            state: SegmentState::Done,
                            attempt: 1,
                            error: None,
                        });
                    }
                    Err(error) => {
                        let entry = failed.entry(index).or_insert((0, String::new()));
                        entry.0 += 1;
                        entry.1 = error.to_string();
                        reporter.event(&Event::Segment {
                            index,
                            file,
                            state: SegmentState::Failed,
                            attempt: entry.0,
                            error: Some(entry.1.clone()),
                        });
                    }
                }
            }
        }
        for segment in &jobs {
            if !ok.contains_key(&segment.index) && fetch::valid_dec_file(&dec_dir, segment.index) {
                ok.insert(segment.index, segment.file.clone());
            }
        }

        if progressed {
            idle = 0;
        } else {
            idle += 1;
        }

        // The GUI gets a sample every poll; a terminal user still sees the counters only every
        // ten seconds, so the cadence they are used to does not change.
        reporter.event(&Event::Progress {
            stage: Stage::Scan,
            keys: known.len(),
            urls: urls.len(),
            segments: jobs.len(),
            done: ok.len(),
            failed: failed.len(),
            elapsed_secs: started.elapsed().as_secs(),
        });
        if last_report.elapsed() > Duration::from_secs(10) {
            last_report = Instant::now();
            reporter.info(format!(
                "  keys={:<5} urls={:<5} segments={:<5} done={:<5} failed={:<4} new={fetched} unreachable={unreachable} elapsed={}s",
                known.len(),
                urls.len(),
                jobs.len(),
                ok.len(),
                failed.len(),
                started.elapsed().as_secs()
            ));
        }

        // The visible segment set grows as the lesson plays, so "everything known is done" is
        // not the same as "the lesson is complete"; keep polling and let the idle limit or the
        // stop signal end the run.
        let known: Vec<u32> = jobs.iter().map(|segment| segment.index).collect();
        if !known.is_empty() && known.iter().all(|index| ok.contains_key(index)) && idle == 0 {
            reporter.info("  caught up with the player; keep playing to reveal more segments");
        }

        // Waiting cannot fill a gap the playhead already ran past -- those keys were never
        // computed. Walk the playhead back to the earliest one and let it decrypt again.
        let gap = seen.iter().find(|index| !ok.contains_key(index)).copied();
        if options.sweep && sweeps_left > 0 && idle >= SWEEP_AFTER {
            if let Some(target) = gap {
                reporter.info(format!(
                    "  stalled {idle} poll(s) with a gap behind the playhead; sweeping back to index {target}"
                ));
                sweeps_left -= 1;
                match seek::seek_window_to(harvester, target, options.press_gap, reporter) {
                    Ok(true) => {
                        reporter.info("  playhead is inside the gap; letting the player re-decrypt");
                        idle = 0;
                        reporter.sleep(options.poll);
                        continue;
                    }
                    Ok(false) => {
                        // Seek keys are not bound in this build: stop trying, stay a passive
                        // observer rather than hammering the player.
                        reporter.info("  sweep unavailable; waiting for manual playback instead");
                        sweeps_left = 0;
                    }
                    Err(error) => reporter.info(format!("  sweep failed: {error}")),
                }
            }
        }

        if idle >= options.idle_limit {
            reporter.info(format!("no progress for {idle} polls; stopping"));
            break;
        }
        reporter.sleep(options.poll);
    }

    reporter.event(&Event::Stage {
        name: Stage::Scan,
        state: StageState::End,
        detail: String::new(),
    });

    finish(&dec_dir, options, &ok, cancelled, reporter)
}

fn finish(
    dec_dir: &std::path::Path,
    options: &GrabOptions,
    ok: &BTreeMap<u32, String>,
    cancelled: bool,
    reporter: &Reporter,
) -> Result<()> {
    if ok.is_empty() {
        reporter.info("nothing decrypted yet; keep the lesson playing and rerun");
        reporter.event(&Event::Finished {
            status: Status::Nothing,
            exit_code: evmedia_contract::exit::OK,
            message: String::new(),
        });
        return Ok(());
    }

    let indexes: Vec<u32> = ok.keys().copied().collect();
    let outcome = media::merge_lesson(dec_dir, &options.output, &indexes, reporter)?;

    let status = if cancelled {
        Status::Cancelled
    } else if outcome.complete {
        Status::Complete
    } else {
        Status::Partial
    };

    if options.mp4 && outcome.complete {
        reporter.event(&Event::Stage {
            name: Stage::Remux,
            state: StageState::Begin,
            detail: String::new(),
        });
        let mp4 = options.output.join("lesson.mp4");
        media::remux_mp4(&outcome.path, &mp4, reporter)?;
        reporter.event(&Event::Stage {
            name: Stage::Remux,
            state: StageState::End,
            detail: String::new(),
        });
    } else if options.mp4 {
        reporter.info(
            "refusing to remux an incomplete merge; play the rest and rerun (segments are cached)",
        );
    }

    reporter.event(&Event::Finished {
        status,
        exit_code: evmedia_contract::exit::OK,
        message: format!("merged {} segment(s)", outcome.count),
    });
    Ok(())
}

//! The sweep: what the loop does when the lesson has a gap behind the playhead.
//!
//! A segment the playhead ran past was never decrypted, so its key was never computed and no
//! amount of waiting produces it. The only cure is to move the playhead back onto it — which means
//! the loop has to *notice* the gap, and the gap is invisible to anything that only looks at
//! segments it already holds keys for.
//!
//! These tests assert where the playhead ended up, not which index a seek was asked for. That is a
//! stronger claim: it survives a change of stepping strategy, and it is what the caller actually
//! depends on.

mod harvest_fixture;

use evmedia_contract::Reporter;
use evmedia_core::harvest::grab;
use harvest_fixture::{options, scratch, segment_key, stage};
use std::time::Duration;

/// The gap the sweep exists for: a segment with a context and a URL but no key. Moving the
/// playhead onto it is the only thing that can produce one.
#[test]
fn a_gap_behind_the_playhead_makes_the_loop_move_the_playhead_onto_it() {
    let output = scratch("sweep");
    let (fixture, plains) = stage(&output, 6);
    let file = fixture.forget_key(3);
    // The playhead sits at the start of the lesson and the gap is at index 3, so covering it
    // takes three presses of one segment each.
    fixture.unlock_on_step(vec![(3, (file, segment_key(3)))]);

    let mut opts = options(&output);
    opts.sweep = true;
    opts.poll = Duration::from_millis(1);
    opts.idle_limit = 20;
    grab::run(&fixture, &opts, &Reporter::silent()).unwrap();

    let (low, high) = fixture.window_at();
    assert!(low <= 3 && 3 <= high, "the playhead must end up covering the gap, not {low}..{high}");
    assert_eq!(fixture.steps(), vec![(false, 3)], "three segments forward, one press each");
    assert_eq!(
        std::fs::read(output.join("lesson.ts")).expect("lesson.ts"),
        plains.concat(),
        "the segment the playhead skipped must end up in the merge"
    );
}

/// A source whose seek keys are unbound says so by not moving, and the loop must believe it the
/// first time rather than hammering the player for the rest of the run.
#[test]
fn a_source_that_cannot_seek_is_asked_once_and_then_left_alone() {
    let output = scratch("nosweep");
    let (fixture, _) = stage(&output, 6);
    fixture.forget_key(3);
    fixture.set_stuck(true);

    let mut opts = options(&output);
    opts.sweep = true;
    opts.poll = Duration::from_millis(1);
    opts.idle_limit = 40;
    grab::run(&fixture, &opts, &Reporter::silent()).unwrap();

    assert_eq!(fixture.steps().len(), 1, "an unbound seek must be tried once, not repeatedly");
    assert_eq!(fixture.window_at(), (0, 0), "and the playhead must not have moved");
    assert!(output.join("lesson.partial.ts").exists());
}

/// The other half of that contract: a playhead that moves and a gap that still never fills must
/// still terminate. Without the attempt cap this is an infinite loop.
#[test]
fn a_sweep_that_never_helps_gives_up_rather_than_looping_forever() {
    let output = scratch("sweepburn");
    let (fixture, _) = stage(&output, 6);
    fixture.forget_key(3);
    // The playhead moves, but nothing is registered as arriving, so the key never appears — the
    // case where a seek can report success forever without the lesson getting any closer.

    let mut opts = options(&output);
    opts.sweep = true;
    opts.poll = Duration::from_millis(1);
    opts.idle_limit = 50;
    let started = std::time::Instant::now();
    grab::run(&fixture, &opts, &Reporter::silent()).unwrap();

    assert!(started.elapsed() < Duration::from_secs(10), "the sweep must be bounded");
    assert_eq!(fixture.steps().len(), 1, "and the playhead must not be walked over and over");
    assert!(
        output.join("lesson.partial.ts").exists(),
        "the gap is still a gap, and the merge must say so"
    );
}

//! A stand-in for a live player, shared by the harvest-loop tests.
//!
//! This is the point of the `Harvester` seam: the loop's real behaviour — resume, retry, the
//! completeness verdict, the merge, the sweep — can be tested with no player, no Windows and no
//! network. Ciphertext is pre-seeded into `enc/`, so nothing has to reach for a URL except in the
//! one test that deliberately takes it away.
//!
//! The fixture models two things about a real player that are easy to miss, and both are
//! load-bearing:
//!
//! * A candidate is only offered while its ciphertext is **on disk**. That is the real
//!   constraint — a key is found by testing it against the segment's bytes — and it is what makes
//!   the download-before-keys ordering testable rather than merely asserted.
//! * The index list and the key list are **independent**. The player holds a context for a
//!   segment it has not decrypted, and a segment with no key is exactly the gap a sweep exists to
//!   find, so `indexes()` cannot be derived from `keys()`.
#![allow(dead_code)]

use aes::Aes256;
use ecb::cipher::{block_padding::NoPadding, BlockEncryptMut, KeyInit};
use evmedia_core::crypto::{key_from_text, mask_from_filename};
use evmedia_core::harvest::{seek::Playhead, GrabOptions, Harvester};
use std::{
    collections::{BTreeMap, BTreeSet, HashMap},
    io::{Read, Write},
    net::TcpListener,
    path::{Path, PathBuf},
    sync::Mutex,
    time::Duration,
};

/// Eight packets, not four. The key probe reads only the first four — 752 bytes — so anything
/// that must survive a *failed decryption* while still being solvable has to live past that.
pub const PACKETS: usize = 8;
pub const SEGMENT_BYTES: usize = 188 * PACKETS;

struct State {
    /// Filename -> index: the contexts the player is holding, whether decrypted or not.
    indexes: HashMap<String, u32>,
    /// Index -> (filename, key), for the segments whose key exists.
    keys: BTreeMap<u32, (String, String)>,
    urls: HashMap<String, String>,
    /// Where the encrypted segments live; a candidate is only offered once its bytes are here.
    enc: PathBuf,
    /// Where the playhead is, as the range of lesson indexes whose key is live.
    ///
    /// This is the fixture's counterpart of `WinSource`'s window: the thing the seek reads to
    /// decide whether it has arrived and how far one press moved. It starts at the beginning of
    /// the lesson, which is where a player that has just opened one sits.
    window: (u32, u32),
    /// Every step the loop posted, in order: whether it went back, and how many presses.
    steps: Vec<(bool, usize)>,
    /// When set, stepping changes nothing — a player whose seek keys are bound to nothing.
    stuck: bool,
    /// Keys the player produces because the playhead moved onto the segment.
    ///
    /// This is what makes a sweep observable end to end. Nothing else can produce a key for a gap:
    /// the player computes it when it decrypts that segment, and it only decrypts it because the
    /// playhead arrived.
    unlock_on_step: Vec<(u32, (String, String))>,
    /// Make the live-context source the *only* one, so the loop's use of it is observable.
    ///
    /// Off by default, which keeps every other test on the candidate path. With it on, a key can
    /// come from nowhere else: if the loop ignored `keys()` the lesson would stay empty, and that
    /// is the point.
    slot_only: bool,
}

pub struct Fixture(Mutex<State>);

impl Fixture {
    fn lock(&self) -> std::sync::MutexGuard<'_, State> {
        self.0.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// Drop a key, as a player that never decrypted that segment would. The context stays: it is
    /// the gap the sweep has to see.
    pub fn forget_key(&self, index: u32) -> String {
        let mut state = self.lock();
        let (file, _) = state.keys.remove(&index).expect("the fixture has that key");
        file
    }

    pub fn forget_url(&self, file: &str) {
        self.lock().urls.remove(file);
    }

    pub fn file_of(&self, index: u32) -> String {
        self.lock().keys.get(&index).expect("the fixture has that key").0.clone()
    }

    pub fn key_of(&self, index: u32) -> String {
        self.lock().keys.get(&index).expect("the fixture has that key").1.clone()
    }

    pub fn restore_key(&self, index: u32, file: String, key: String) {
        self.lock().keys.insert(index, (file, key));
    }

    /// Where the playhead has arrived.
    pub fn window_at(&self) -> (u32, u32) {
        self.lock().window
    }

    /// Every step the loop posted, in order.
    pub fn steps(&self) -> Vec<(bool, usize)> {
        self.lock().steps.clone()
    }

    /// Make stepping change nothing, as a player whose seek keys are bound to nothing does.
    pub fn set_stuck(&self, stuck: bool) {
        self.lock().stuck = stuck;
    }

    /// Keys the player produces when the playhead lands on a segment.
    pub fn unlock_on_step(&self, entries: Vec<(u32, (String, String))>) {
        self.lock().unlock_on_step = entries;
    }

    /// Answer every question from the live contexts and from nowhere else.
    pub fn use_only_live_contexts(&self) {
        self.lock().slot_only = true;
    }

    /// Repoint every URL at a real server, for the one test that has to fetch.
    pub fn retarget(&self, base: &str) {
        let mut state = self.lock();
        let rewired: Vec<(String, String)> = state
            .keys
            .iter()
            .map(|(index, (file, _))| (file.clone(), format!("{base}/{index}.ts")))
            .collect();
        for (file, url) in rewired {
            state.urls.insert(file, url);
        }
    }
}

impl Harvester for Fixture {
    fn pid(&self) -> u32 {
        4242
    }

    /// The player's live contexts: index, filename and key together, with nothing to work out.
    ///
    /// Empty unless `slot_only` is set. That is not squeamishness about the source — it is what
    /// keeps the *other* tests honest. Every one of them asserts something about the candidate
    /// path or about what happens when a key is missing, and a fixture that quietly answered
    /// every question from a complete map would let them all pass without exercising anything.
    fn keys(&self) -> BTreeMap<u32, (String, String)> {
        let state = self.lock();
        if !state.slot_only {
            return BTreeMap::new();
        }
        state.keys.clone()
    }

    /// Exactly the real shape: the key text is in memory, and it can only be *used* once the
    /// segment's bytes are somewhere to test it against.
    fn candidates(&self) -> BTreeSet<String> {
        let state = self.lock();
        if state.slot_only {
            return BTreeSet::new();
        }
        state
            .keys
            .values()
            .filter(|(file, _)| state.enc.join(file).exists())
            .map(|(_, key)| key.clone())
            .collect()
    }

    fn indexes(&self) -> HashMap<String, u32> {
        self.lock().indexes.clone()
    }

    fn urls(&self) -> HashMap<String, String> {
        self.lock().urls.clone()
    }

    fn diagnose(&self) -> String {
        "fixture".to_string()
    }
}

/// The fixture's playhead.
///
/// A press moves the window one lesson index. A real player moves further per press, which is what
/// the seek's calibration exists to discover; keeping it at exactly one here makes the arithmetic
/// in the sweep tests checkable by hand.
impl Playhead for Fixture {
    fn window(&self) -> Option<(u32, u32)> {
        Some(self.lock().window)
    }

    fn step(&self, back: bool, count: usize, _gap: Duration) {
        let mut state = self.lock();
        state.steps.push((back, count));
        if state.stuck {
            return;
        }
        let shift = count as i64 * if back { -1 } else { 1 };
        let moved = |value: u32| (value as i64 + shift).max(0) as u32;
        state.window = (moved(state.window.0), moved(state.window.1));

        // Decrypting a segment is what the player does when the playhead lands on it, and it is
        // the only thing that ever produces a key for one.
        let (low, high) = state.window;
        let arrived: Vec<(u32, (String, String))> = state
            .unlock_on_step
            .iter()
            .filter(|(index, _)| (low..=high).contains(index))
            .cloned()
            .collect();
        for (index, entry) in arrived {
            state.keys.insert(index, entry);
        }
    }
}

pub fn segment_name(index: u32) -> String {
    format!("119354-{index:08x}-0000-4000-8000-000000000000.ts")
}

pub fn segment_key(index: u32) -> String {
    format!("{index:032x}")
}

/// Deterministic plaintext that is a whole number of TS packets and of AES blocks.
fn segment_plain(index: u32) -> Vec<u8> {
    let mut data = vec![0u8; SEGMENT_BYTES];
    for packet in 0..PACKETS {
        let base = packet * 188;
        data[base] = 0x47;
        data[base + 3] = 0x10;
        for offset in 4..188 {
            data[base + offset] = ((index as usize * 31 + packet * 7 + offset) % 251) as u8;
        }
    }
    data
}

fn encrypt(plain: &[u8], key: &[u8; 32], mask: &[u8; 16]) -> Vec<u8> {
    let mut buffer = plain.to_vec();
    let length = plain.len();
    ecb::Encryptor::<Aes256>::new_from_slice(key)
        .unwrap()
        .encrypt_padded_mut::<NoPadding>(&mut buffer, length)
        .unwrap();
    for (index, byte) in buffer.iter_mut().enumerate() {
        *byte ^= mask[index % 16];
    }
    buffer
}

/// Lay out `output/enc` with the ciphertext for segments `0..count`, and describe them.
pub fn stage(output: &Path, count: u32) -> (Fixture, Vec<Vec<u8>>) {
    let enc = output.join("enc");
    std::fs::create_dir_all(&enc).unwrap();
    let mut indexes = HashMap::new();
    let mut keys = BTreeMap::new();
    let mut urls = HashMap::new();
    let mut plains = Vec::new();
    for index in 0..count {
        let file = segment_name(index);
        let key_text = segment_key(index);
        let plain = segment_plain(index);
        let cipher = encrypt(
            &plain,
            &key_from_text(&key_text).unwrap(),
            &mask_from_filename(&file),
        );
        std::fs::write(enc.join(&file), &cipher).unwrap();
        indexes.insert(file.clone(), index);
        keys.insert(index, (file.clone(), key_text));
        urls.insert(file, format!("http://example.invalid/{index}.ts?sign=x"));
        plains.push(plain);
    }
    let fixture = Fixture(Mutex::new(State {
        indexes,
        keys,
        urls,
        enc,
        window: (0, 0),
        steps: Vec::new(),
        stuck: false,
        unlock_on_step: Vec::new(),
        slot_only: false,
    }));
    (fixture, plains)
}

/// A minimal HTTP/1.1 server that serves the staged ciphertext from memory.
///
/// The download path cannot be reached with the ciphertext already on disk, and every other test
/// deliberately starts that way. Rather than reaching for the network, this serves the exact
/// bytes the fixtures encrypt, so the test stays hermetic and fast.
pub fn serve(bodies: HashMap<String, Vec<u8>>) -> (String, std::thread::JoinHandle<()>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind a loopback port");
    let port = listener.local_addr().unwrap().port();
    let handle = std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { break };
            let mut head = Vec::new();
            let mut byte = [0u8; 1];
            while !head.ends_with(b"\r\n\r\n") {
                match stream.read(&mut byte) {
                    Ok(1) => head.push(byte[0]),
                    _ => break,
                }
            }
            let request = String::from_utf8_lossy(&head).into_owned();
            let path = request.split_whitespace().nth(1).unwrap_or_default();
            match bodies.get(path) {
                Some(body) => {
                    let header = format!(
                        "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        body.len()
                    );
                    let _ = stream.write_all(header.as_bytes());
                    let _ = stream.write_all(body);
                }
                None => {
                    let _ = stream.write_all(
                        b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                    );
                }
            }
        }
    });
    (format!("http://127.0.0.1:{port}"), handle)
}

pub fn scratch(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("evmedia-grab-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

pub fn options(output: &Path) -> GrabOptions {
    GrabOptions {
        output: output.to_path_buf(),
        jobs: 4,
        poll: Duration::from_millis(5),
        idle_limit: 3,
        attempts: 2,
        mp4: false,
        // Off by default, so a test that wants a sweep has to ask for one and say where the
        // playhead is. Every other test stays out of the playhead's way entirely.
        sweep: false,
        press_gap: Duration::from_millis(1),
    }
}

//! The live Windows source: a [`Player`] presented as a [`Harvester`].
//!
//! It is also the [`Playhead`], because the harvest loop steers the player through the same seam it
//! reads it through. Having one object implement both is the point of the merge: there is nothing
//! here that a test would have to stand in for twice.

use crate::{playhead, process::Player};
use anyhow::Result;
use evmedia_core::harvest::{seek::Playhead, Harvester};
use std::{
    collections::{BTreeMap, BTreeSet, HashMap},
    time::Duration,
};

pub struct WinSource {
    player: Player,
}

impl WinSource {
    pub fn open(pid: u32) -> Result<Self> {
        Ok(Self { player: Player::open(pid)? })
    }

    pub fn player(&self) -> &Player {
        &self.player
    }
}

impl Harvester for WinSource {
    fn pid(&self) -> u32 {
        self.player.pid()
    }

    fn keys(&self) -> BTreeMap<u32, (String, String)> {
        self.player.active_keys()
    }

    fn candidates(&self) -> BTreeSet<String> {
        self.player.hex_candidates()
    }

    fn indexes(&self) -> HashMap<String, u32> {
        self.player.segment_indexes()
    }

    fn urls(&self) -> HashMap<String, String> {
        self.player.segment_urls()
    }

    fn diagnose(&self) -> String {
        self.player.diagnose()
    }
}

impl Playhead for WinSource {
    /// The range of lesson indexes whose key is live right now.
    ///
    /// Read from the keys, not from every context the player holds. The player keeps a context for
    /// each segment it has touched, and on a real lesson that is the whole lesson — a recorded dump
    /// in the research bench shows 134 contexts held with only 2 decrypted. A window measured from
    /// those spans everything, so a seek is always told it has already arrived and never moves.
    ///
    /// A missing player window is deliberately not checked here. With nothing to post to, stepping
    /// changes nothing, and the seek reports that the steps had no effect — which is true, and more
    /// honest than blaming the key window for it.
    fn window(&self) -> Option<(u32, u32)> {
        let live = self.player.active_keys();
        Some((*live.keys().next()?, *live.keys().next_back()?))
    }

    fn step(&self, back: bool, count: usize, gap: Duration) {
        let Some(hwnd) = playhead::player_window(self.player.pid()) else {
            return;
        };
        let key = if back { playhead::STEP_BACK } else { playhead::STEP_FORWARD };
        playhead::post_key(hwnd, key, count, gap);
    }
}

