2	//!
3	//! The algorithm is portable and lives here so it can be tested without a player. Everything it
4	//! needs from one is two things — where the window is now, and how to step — which `evmedia-win`
5	//! supplies from the real player (a `WM_KEYDOWN`/`WM_KEYUP` post to its own window) and a test
6	//! supplies from a counter.
7	//!
8	//! Why it needs the playhead at all: a segment's key exists only once the player has decrypted it
9	//! for playback, so a gap left behind the playhead can only be filled by putting the playhead back
10	//! inside it and letting the read-ahead decrypt it again.
11	//!
12	//! The window doubles as the position readout. There is no other feedback available — the player's
13	//! rendering surface cannot be read — so each round measures how far a batch of steps moved the
14	//! window and sizes the next batch from that, rather than assuming a step size.
15	
16	use anyhow::Result;
17	use evmedia_contract::Reporter;
18	use std::time::Duration;
19	
20	/// What the seek needs from a player.
21	pub trait Playhead {
22	    /// The lowest and highest segment index whose key is live right now.
23	    ///
24	    /// `None` means the player is holding nothing, which is the caller's cue to stop.
25	    ///
26	    /// This must be the *keyed* set rather than every segment the player has a context for. The
27	    /// player keeps a context for each segment it has touched, and on a real lesson that is the
28	    /// whole lesson: a recorded dump in `tools/parser-tools/dump_contexts.json` shows 134 contexts
29	    /// held with only 2 decrypted. A window measured from those spans everything, so the
30	    /// "is the target already inside?" test below passes for a segment that was never decrypted
31	    /// and the seek posts no keys at all while reporting success.
32	    fn window(&self) -> Option<(u32, u32)>;
33	
34	    /// Step the playhead `count` times, backwards when `back` is set.
35	    fn step(&self, back: bool, count: usize, gap: Duration);
36	}
37	
38	/// Rounds to try before giving up on reaching the target.
39	const MAX_ROUNDS: usize = 8;
40	/// Bounds on one batch, so a bad measurement cannot fire thousands of keystrokes.
41	const MIN_PRESSES: f64 = 2.0;
42	const MAX_PRESSES: f64 = 400.0;
43	/// The estimate of segments-per-press never drops below this, which is what stops it collapsing to
44	/// zero after a round that moved nothing and then clamping every later batch to the maximum.
45	const MIN_PER_PRESS: f64 = 0.05;
46	
47	/// Move the playhead until `target` sits inside the live window.
48	///
49	/// Generic over the playhead rather than taking `&dyn Playhead` so that a caller holding a
50	/// `&dyn Harvester` can pass it straight in: `Harvester` has `Playhead` as a supertrait, so the
51	/// object satisfies this bound without an upcast.
52	///
53	/// Returns false when the steps turn out to have no effect, so the caller can stop asking and
54	/// simply wait instead of hammering the player.
55	pub fn seek_window_to<P: Playhead + ?Sized>(
56	    playhead: &P,
57	    target: u32,
58	    press_gap: Duration,
59	    reporter: &Reporter,
60	) -> Result<bool> {
61	    // Segments moved per step. The first batch guesses 1 and the measurement corrects it.
62	    let mut per_press = 1.0f64;
63	    for round in 1..=MAX_ROUNDS {
64	        let Some((current, highest)) = playhead.window() else {
65	            reporter.info("  player is holding no segment window; nothing to aim at");
66	            return Ok(false);
67	        };
68	        if current <= target && target <= highest {
69	            return Ok(true);
70	        }
71	        let back = target < current;
72	        let distance = if back { (current - target) as f64 } else { (target - highest) as f64 };
73	        let presses = (distance / per_press).clamp(MIN_PRESSES, MAX_PRESSES) as usize;
74	        playhead.step(back, presses, press_gap);
75	
76	        let Some((moved, moved_high)) = playhead.window() else {
77	            return Ok(false);
78	        };
79	        if moved == current && moved_high == highest {
80	            reporter.info(format!("  seek keys had no effect (window stayed {current}..{highest})"));
81	            return Ok(false);
82	        }
83	        let travelled = if back {
84	            (current as i64 - moved as i64).max(0) as f64
85	        } else {
86	            (moved_high as i64 - highest as i64).max(0) as f64
87	        };
88	        per_press = (travelled / presses as f64).max(MIN_PER_PRESS);
89	        reporter.info(format!(
90	            "  sweep {round}: {presses} x step-{} moved the window {current}..{highest} -> {moved}..{moved_high} (~{per_press:.2} seg/press)",
91	            if back { "back" } else { "forward" }
92	        ));
93	    }
94	    let covered = playhead
95	        .window()
96	        .is_some_and(|(low, high)| low <= target && target <= high);
97	    if !covered {
98	        reporter.info(format!("  sweep did not converge on index {target}"));
99	    }
100	    Ok(covered)
