1	#!/usr/bin/env python3
2	"""Chase EVPlayer2's segment-key derivation.
3	
4	Finding so far: the AES code that decrypts segments lives in PlayerLibRender56_vs.dll
5	(RVA 0x792c78 reads the inverse S-box), but its *callers* sit in dynamically allocated
6	executable memory (heap addresses that belong to no module) -- which is why static
7	analysis of the DLL never finds the MD5/derivation the key = MD5(tk+file+salt) implies.
8	
9	This script therefore walks the live call chain and watches for the key store:
10	
11	  A) breakpoint at dll+0x792c78 (AES decrypt): collect the unique caller addresses, then
12	     attach to each and dump registers, pointed-to strings, the stack, and the first
13	     bytes of the caller's code.
14	
15	  B) write watch on ctx+0x120 (the 32-byte key field) of playback-context objects that
16	     are not yet "ready", so we catch the instruction that stores a freshly derived key.
17	
18	Usage:  <python> -u watch_key.py [seconds]     (default 240)
19	Play a video while it runs and keep it playing.
20	"""
21	import frida
22	import os
23	import sys
24	import time
25	
26	JS = r"""
27	'use strict';
28	var DLL = 'PlayerLibRender56_vs.dll';
29	var dll = Process.getModuleByName(DLL);
30	var AES_DECRYPT_RVA = 0x792c78;
31	
32	function modOff(a) {
33	  try {
34	    var mo = Process.findModuleByAddress(a);
35	    if (!mo) return a.toString() + ' <heap-code>';
36	    return mo.name + '+0x' + a.sub(mo.base).toString(16);
37	  } catch (e) { return a.toString(); }
38	}
39	function bytesToStr(buf) {
40	  var u = new Uint8Array(buf); var s = '';
41	  for (var i = 0; i < u.length; i++) s += String.fromCharCode(u[i]);
42	  return s;
43	}
44	function stringsIn(ptrAddr, len) {
45	  var out = [];
46	  try {
47	    var u = new Uint8Array(ptrAddr.readByteArray(len));
48	    var cur = '';
49	    for (var i = 0; i < u.length; i++) {
50	      var c = u[i];
51	      if (c >= 32 && c < 127) cur += String.fromCharCode(c);
52	      else { if (cur.length >= 5) out.push(cur); cur = ''; }
53	    }
54	    if (cur.length >= 5) out.push(cur);
55	  } catch (e) {}
56	  return out;
57	}
58	function codeAt(a, n) {
59	  try { return bytesToStr(a.readByteArray(n)).replace(/[^\x20-\x7e]/g, '.'); } catch (e) { return null; }
60	}
61	
62	// ---------- A) callers of the AES decrypt loop ----------
63	var callers = {}, callerCount = 0;
64	function inspectCaller(addr) {
65	  var p = ptr(addr);
66	  var id = p.toString();
67	  if (callers[id]) return;
68	  callers[id] = 1;
69	  callerCount++;
70	  send({t: 'log', msg: 'A) new caller #' + callerCount + ': ' + modOff(p)});
71	  try {
72	    Interceptor.attach(p, {
73	      onEnter: function () {
74	        var ctx = this.context;
75	        var regs = ['rax','rbx','rcx','rdx','rsi','rdi','rbp','r8','r9','r10','r11','r12','r13','r14','r15'];
76	        var strs = {};
77	        regs.forEach(function (rn) {
78	          try {
79	            var s = ctx[rn].readCString(200);
80	            if (s && s.length >= 4) { var ok = 0; for (var i = 0; i < s.length; i++) { var c = s.charCodeAt(i); if (c >= 32 && c < 127) ok++; } if (ok / s.length > 0.85) strs[rn] = s; }
81	          } catch (e) {}
82	        });
83	        send({t: 'caller-hit', at: modOff(p), strs: strs,
84	              stack: stringsIn(ctx.rsp, 0x400),
85	              bt: Thread.backtrace(ctx, Backtracer.ACCURATE).map(modOff)});
86	      }
87	    });
88	  } catch (e) { send({t: 'err', where: 'attach-caller', e: String(e)}); }
89	}
90	
91	var aesHits = 0;
92	Interceptor.attach(dll.base.add(AES_DECRYPT_RVA), {
93	  onEnter: function () {
94	    try {
95	      var bt = Thread.backtrace(this.context, Backtracer.ACCURATE);
96	      for (var i = 0; i < bt.length && i < 3; i++) inspectCaller(bt[i]);
97	      if (aesHits++ === 0) send({t: 'aes-first', bt: bt.map(modOff), stack: stringsIn(this.context.rsp, 0x600)});
98	    } catch (e) {}
99	  }
100	});
101	send({t: 'log', msg: 'A) armed at ' + DLL + '+0x' + AES_DECRYPT_RVA.toString(16)});
102	
103	// ---------- B) write watch on pending contexts' key field ----------
104	function readStr(obj, off) {
