1	//! The harvest loop's core behaviour: resume, retry, the completeness verdict, the merge, and
2	//! the ordering of download against key derivation. Everything here runs against a fixture — no
3	//! player, no Windows, no network.
4	
5	mod harvest_fixture;
6	
7	use evmedia_contract::Reporter;
8	use evmedia_core::harvest::grab;
9	use harvest_fixture::{options, scratch, segment_name, serve, stage};
10	use std::collections::HashMap;
11	use std::time::Duration;
12	
13	#[test]
14	fn a_complete_lesson_merges_to_lesson_ts() {
15	    let output = scratch("complete");
16	    let (fixture, plains) = stage(&output, 6);
17	    grab::run(&fixture, &options(&output), &Reporter::silent()).unwrap();
18	
19	    let merged = std::fs::read(output.join("lesson.ts")).expect("lesson.ts");
20	    let expected: Vec<u8> = plains.concat();
21	    assert_eq!(merged, expected);
22	    assert!(!output.join("lesson.partial.ts").exists());
23	    // Every segment is cached decrypted, independently of the merge.
24	    for index in 0..6u32 {
25	        assert!(output.join("dec").join(format!("{index:06}.ts")).exists());
26	    }
27	}
28	
29	#[test]
30	fn a_lesson_with_a_hole_stays_partial_and_is_never_called_lesson_ts() {
31	    let output = scratch("hole");
32	    let (fixture, plains) = stage(&output, 6);
33	    // The player never decrypted index 3, so its key does not exist. Its URL is gone too, which
34	    // is how the loop knows the segment is not part of this lesson rather than a gap in it.
35	    let file = fixture.forget_key(3);
36	    fixture.forget_url(&file);
37	    grab::run(&fixture, &options(&output), &Reporter::silent()).unwrap();
38	
39	    assert!(!output.join("lesson.ts").exists(), "a hole must not produce a complete-looking file");
40	    let merged = std::fs::read(output.join("lesson.partial.ts")).expect("lesson.partial.ts");
41	    let expected: Vec<u8> = [0usize, 1, 2, 4, 5].iter().flat_map(|i| plains[*i].clone()).collect();
42	    assert_eq!(merged, expected);
43	}
44	
45	#[test]
46	fn a_rerun_resumes_and_reproduces_the_same_bytes() {
47	    let output = scratch("resume");
48	    let (fixture, plains) = stage(&output, 5);
49	    grab::run(&fixture, &options(&output), &Reporter::silent()).unwrap();
50	    let first = std::fs::read(output.join("lesson.ts")).unwrap();
51	
52	    // Delete the ciphertext cache: if the rerun needed the network it would now fail, so this
53	    // also proves it resumed from `dec/` rather than re-downloading.
54	    std::fs::remove_dir_all(output.join("enc")).unwrap();
55	    grab::run(&fixture, &options(&output), &Reporter::silent()).unwrap();
56	    let second = std::fs::read(output.join("lesson.ts")).unwrap();
57	
58	    assert_eq!(first, second);
59	    assert_eq!(first, plains.concat());
60	}
61	
62	#[test]
63	fn a_segment_that_cannot_be_decrypted_is_given_up_on_rather_than_retried_forever() {
64	    let output = scratch("corrupt");
