use std::io::Write;
use std::time::Duration;

// A target whose writes are ours to control. The point is to find out what frida's
// MemoryAccessMonitor reports for writes of different widths and starting offsets -- in particular
// whether a write that spans the watched bytes but starts before them arrives with the spanning
// address or with the watched address.
fn main() {
    let layout = std::alloc::Layout::from_size_align(8192, 4096).unwrap();
    let base = unsafe { std::alloc::alloc_zeroed(layout) };
    println!("pid={}", std::process::id());
    println!("base={:p}", base);
    println!("field={:p}", unsafe { base.add(0x120) });
    std::io::stdout().flush().unwrap();

    // Offset 0x120 from the base is the "field". The base is page-aligned, so page = base and the
    // field sits 0x120 bytes into it.
    let mut n: u8 = 0;
    loop {
        std::thread::sleep(Duration::from_millis(700));
        n = n.wrapping_add(1);

        // (1) exactly the watched 32 bytes, starting at the field
        unsafe { std::ptr::write_bytes(base.add(0x120), n, 32) };
        println!("A exact-32-at-field n={n}");
        std::io::stdout().flush().unwrap();

        std::thread::sleep(Duration::from_millis(700));
        n = n.wrapping_add(1);

        // (2) a span that crosses the field but starts 0x20 bytes before it
        unsafe { std::ptr::write_bytes(base.add(0x100), n, 0x60) };
        println!("B spans-field-starting-earlier n={n}");
        std::io::stdout().flush().unwrap();

        std::thread::sleep(Duration::from_millis(700));
        n = n.wrapping_add(1);

        // (3) one byte at the field's first byte only
        unsafe { std::ptr::write_volatile(base.add(0x120), n) };
        println!("C one-byte-at-field n={n}");
        std::io::stdout().flush().unwrap();
    }
}

