import subprocess
import sys
import threading
import time

import frida

SRC = r"C:\Users\Yonjay\AppData\Local\Temp\watchprobe\src\main.rs"
EXE = r"C:\Users\Yonjay\AppData\Local\Temp\watchprobe\watchprobe.exe"

JS = r"""
'use strict';
var page = ptr(BASE);
var seen = 0;
MemoryAccessMonitor.enable([{ base: page, size: 0x1000 }], {
  onAccess: function (d) {
    if (seen++ > 60) return;
    send({ t: 'access', op: d.operation, addr: d.address.toString(),
           off: '0x' + d.address.sub(page).toString(16), from: d.from.toString() });
  }
});
send({ t: 'armed', page: page.toString() });
"""


def build():
    r = subprocess.run(['rustc', '-O', '-o', EXE, SRC], capture_output=True, text=True,
                       encoding='utf-8', errors='replace')
    if r.returncode != 0:
        print(r.stderr[-2000:])
        sys.exit(1)
    print('built', EXE)


def main():
    build()
    p = subprocess.Popen([EXE], stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         text=True, encoding='utf-8', errors='replace', bufsize=1)
    lines = []
    frida_msgs = []

    def pump():
        for line in p.stdout:
            lines.append(line.rstrip())

    t = threading.Thread(target=pump, daemon=True)
    t.start()

    for _ in range(100):
        if len(lines) >= 3:
            break
        time.sleep(0.05)
    pid = int(lines[0].split('=')[1])
    base = lines[1].split('=')[1]
    field = lines[2].split('=')[1]
    print('target pid=%d base=%s field=%s' % (pid, base, field))

    session = frida.attach(pid)
    script = session.create_script(JS.replace('BASE', '"%s"' % base))
    script.on('message', lambda m, d: frida_msgs.append(m))
    script.load()
    time.sleep(9.0)
    session.detach()
    p.kill()

    print()
    print('=== target writes (its own stdout) ===')
    for line in lines[3:24]:
        print('  ', line)
    print()
    print('=== what MemoryAccessMonitor reported ===')
    for m in frida_msgs:
        pl = m.get('payload') or {}
        if pl.get('t') == 'armed':
            print('   armed on page', pl['page'])
        elif pl.get('t') == 'access':
            print('   %-6s addr=%s off=%s from=%s' % (pl['op'], pl['addr'], pl['off'], pl['from']))
        else:
            print('   ', m.get('type'), str(m.get('description'))[:150])
    print()
    print('=== interpretation ===')
    print('The field is at page+0x120. A write to the field shows up as off=0x120.')
    print('If the "B" writes (which start at page+0x100 and span 0x60 bytes over the field)')
    print('arrive as off=0x100, then a spanning write faults at its FIRST byte, which is what')
    print('decides whether probe_write.py\'s [field, field+32) filter can miss the writer.')


if __name__ == '__main__':
    main()

