import subprocess
import sys
import threading
import time

import frida

SRC = r"C:\Users\Yonjay\AppData\Local\Temp\watchprobe\src\main.rs"
EXE = r"C:\Users\Yonjay\AppData\Local\Temp\watchprobe\watchprobe2.exe"

JS = r"""
'use strict';
var page = ptr(BASE);
var ranges = [{ base: page, size: 0x1000 }];
var count = 0;
var MODE = 'MODE';
function handler(d) {
  if (count++ < 200) {
    send({ t: 'access', op: d.operation, off: '0x' + d.address.sub(page).toString(16),
           from: d.from.toString() });
  }
  if (MODE === 'rearm') {
    try { MemoryAccessMonitor.disable(); } catch (e) {}
    try { MemoryAccessMonitor.enable(ranges, { onAccess: handler }); }
    catch (e) { send({ t: 'rearm-err', e: String(e) }); }
  }
}
MemoryAccessMonitor.enable(ranges, { onAccess: handler });
send({ t: 'armed' });
"""


def build():
    r = subprocess.run(['rustc', '-O', '-o', EXE, SRC], capture_output=True, text=True,
                       encoding='utf-8', errors='replace')
    if r.returncode != 0:
        print(r.stderr[-2000:])
        sys.exit(1)


def run_variant(base, pid, mode, seconds=8.0):
    session = frida.attach(pid)
    script = session.create_script(JS.replace('BASE', '"%s"' % base).replace('MODE', mode))
    msgs = []
    script.on('message', lambda m, d: msgs.append(m))
    script.load()
    time.sleep(seconds)
    session.detach()
    return [m.get('payload') or {} for m in msgs]


def main():
    build()
    p = subprocess.Popen([EXE], stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         text=True, encoding='utf-8', errors='replace', bufsize=1)
    lines = []

    def pump():
        for line in p.stdout:
            lines.append(line.rstrip())

    threading.Thread(target=pump, daemon=True).start()
    for _ in range(100):
        if len(lines) >= 3:
            break
        time.sleep(0.05)
    pid = int(lines[0].split('=')[1])
    base = lines[1].split('=')[1]
    print('target pid=%d base=%s\n' % (pid, base))

    for mode in ('static', 'rearm'):
        before = len(lines)
        payloads = run_variant(base, pid, mode)
        writes = [pl for pl in payloads if pl.get('t') == 'access' and pl.get('op') == 'write']
        reads = [pl for pl in payloads if pl.get('t') == 'access' and pl.get('op') == 'read']
        errs = [pl for pl in payloads if pl.get('t') == 'rearm-err']
        happened = [l for l in lines[before:] if l.startswith(('write', 'read'))]
        print('=== mode=%s ===' % mode)
        print('   target performed : %d memory ops (%d writes, %d reads)'
              % (len(happened), len([h for h in happened if h.startswith('write')]),
                 len([h for h in happened if h.startswith('read')])))
        print('   monitor reported : %d accesses (%d write, %d read)'
              % (len(writes) + len(reads), len(writes), len(reads)))
        for w in writes[:8]:
            print('      %-5s off=%s' % (w['op'], w['off']))
        for e in errs[:2]:
            print('      rearm-err:', e['e'])
        print()


if __name__ == '__main__':
    main()

