use std::io::Write;
use std::time::{Duration, Instant};

// A deliberately HOT page: the target hammers a byte in the watched page. The question is whether
// timer-based re-arming can cope with a page the target touches constantly, or whether it wedges the
// target the way re-arming from inside the callback did.
fn main() {
    let layout = std::alloc::Layout::from_size_align(8192, 4096).unwrap();
    let base = unsafe { std::alloc::alloc_zeroed(layout) };
    println!("pid={}", std::process::id());
    println!("base={:p}", base);
    println!("field={:p}", unsafe { base.add(0x120) });
    std::io::stdout().flush().unwrap();

    let start = Instant::now();
    let mut iterations: u64 = 0;
    // Hammer for 10 seconds, counting iterations, so a slowdown caused by the guard shows up as a
    // lower count than the unguarded baseline.
    while start.elapsed() < Duration::from_secs(10) {
        for _ in 0..50_000 {
            unsafe {
                std::ptr::write_volatile(base.add(0x40), 1u8);
                std::ptr::read_volatile(base.add(0x40));
            }
        }
        iterations += 50_000;
        std::thread::sleep(Duration::from_millis(1));
    }
    println!("iterations={iterations}");
    std::io::stdout().flush().unwrap();
}

