use std::io::Write;
use std::time::Duration;

// Second target: the question is whether a READ consumes the guard, and whether re-arming in the
// callback recovers every subsequent write. Writes and reads are separated by a marker line so the
// two can be correlated.
fn main() {
    let layout = std::alloc::Layout::from_size_align(8192, 4096).unwrap();
    let base = unsafe { std::alloc::alloc_zeroed(layout) };
    println!("pid={}", std::process::id());
    println!("base={:p}", base);
    println!("field={:p}", unsafe { base.add(0x120) });
    std::io::stdout().flush().unwrap();

    let mut n: u8 = 1;
    loop {
        std::thread::sleep(Duration::from_millis(300));

        // a read of a byte in the page, that is NOT a write and NOT the watched byte
        let probe = unsafe { std::ptr::read_volatile(base.add(0x40)) };
        println!("read at +0x40 -> {probe}");

        std::thread::sleep(Duration::from_millis(300));
        unsafe { std::ptr::write_bytes(base.add(0x120), n, 32) };
        println!("write 32 at +0x120 n={n}");

        std::thread::sleep(Duration::from_millis(300));
        unsafe { std::ptr::write_bytes(base.add(0x120), n, 32) };
        println!("write 32 at +0x120 again n={n}");

        n = n.wrapping_add(1);
    }
}

