  try { MemoryAccessMonitor.enable(ranges, { onAccess: handler }); } catch (e) {}
}
enable();
setInterval(function () {
  try { MemoryAccessMonitor.disable(); } catch (e) {}
  enable();
}, __TICK__);
send({ t: 'armed' });
"""


def build():
    r = subprocess.run(['rustc', '-O', '-o', EXE, SRC], capture_output=True, text=True,
                       encoding='utf-8', errors='replace')
    if r.returncode != 0:
        print(r.stderr[-2000:])
        sys.exit(1)


def launch():
    p = subprocess.Popen([EXE], stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         text=True, encoding='utf-8', errors='replace', bufsize=1)
    lines = []
    threading.Thread(target=lambda: [lines.append(l.rstrip()) for l in p.stdout],
                     daemon=True).start()
    for _ in range(200):
        if len(lines) >= 3:
            break
        time.sleep(0.02)
    return p, lines, int(lines[0].split('=')[1]), lines[1].split('=')[1]


