    session = None
    armed = None
    if tick is not None:
        t0 = time.time()
        session = frida.attach(pid)
        script = session.create_script(JS.replace('__BASE__', base).replace('__TICK__', str(tick)))
        script.on('message', lambda m, d: None)
        script.load()
        armed = time.time() - t0
    for _ in range(400):
        if any(l.startswith('iterations=') for l in lines):
            break
        time.sleep(0.05)
    if session:
        session.detach()
    p.kill()
    it = [l for l in lines if l.startswith('iterations=')]
    n = int(it[0].split('=')[1]) if it else -1
    print('%-34s iterations=%d   (attach+arm took %.2fs)' % (label, n, armed or 0.0))
    return n


def main():
    build()
    print('The target hammers a byte in the watched page for ~10s and counts iterations.')
    print('A guard that costs the player a lot of throughput shows up as a much lower count.\n')
    base_n = run('no monitor (baseline)')
    for tick in (20, 100, 500):
        n = run('MemoryAccessMonitor, re-arm %dms' % tick, tick=tick)
        if base_n > 0:
            print('%-34s -> %.1f%% of baseline throughput'
                  % ('  relative', 100.0 * n / base_n))
    print()


if __name__ == '__main__':
    main()

