        script.on('message', lambda m, d: None)
        script.load()
        arm = time.time() - t0

    for _ in range(400):
        if any(l.startswith('iterations=') for l in lines):
            break
        time.sleep(0.05)
    if session:
        session.detach()
    p.kill()
    it = [l for l in lines if l.startswith('iterations=')]
    v = int(it[0].split('=')[1]) if it else -1
    print('%-40s iterations=%-9d (attach+arm %.2fs)' % (label, v, arm))
    return v


def main():
    build()
    print('N pages, each hammered in a tight loop, 8s. Re-arm interval fixed at 100ms.\n')
    for n in (1, 8, 32, 128):
        base_n = run('N=%-4d no monitor' % n, n, None)
        guarded = run('N=%-4d guarded, re-arm 100ms' % n, n, 100)
        if base_n > 0:
            print('%-40s -> %.1f%% of its own baseline' % ('', 100.0 * guarded / base_n))
        print()


if __name__ == '__main__':
    main()

