use std::io::Write;
use std::time::{Duration, Instant};

// N hot pages, to find where the guard stops being free. The answer decides how many playback
// contexts a write watch can cover at once.
fn main() {
    let n: usize = std::env::args().nth(1).and_then(|a| a.parse().ok()).unwrap_or(1);
    let layout = std::alloc::Layout::from_size_align(4096 * n + 4096, 4096).unwrap();
    let base = unsafe { std::alloc::alloc_zeroed(layout) };
    println!("pid={}", std::process::id());
    println!("base={:p}", base);
    println!("pages={n}");
    std::io::stdout().flush().unwrap();

    let addrs: Vec<*mut u8> = (0..n).map(|i| unsafe { base.add(i * 4096 + 0x40) }).collect();
    let start = Instant::now();
    let mut iterations: u64 = 0;
    while start.elapsed() < Duration::from_secs(8) {
        for ptr in &addrs {
            unsafe {
                std::ptr::write_volatile(*ptr, 1u8);
                std::ptr::read_volatile(*ptr);
            }
        }
        iterations += 1;
        std::thread::sleep(Duration::from_micros(200));
    }
    println!("iterations={iterations}");
    std::io::stdout().flush().unwrap();
}

