    std::thread::sleep(Duration::from_millis(300));
    let key = b"3df51fd02753d5605cc3139e66a3561e";
    unsafe { std::ptr::copy_nonoverlapping(key.as_ptr(), base.add(0x120), 32) };
    println!("WROTE the key at +0x120");
    std::io::stdout().flush().unwrap();

    std::thread::sleep(Duration::from_secs(6));
}

