use std::io::Write;
use std::time::Duration;

// Stands in for the player: it reads one byte of the page first (the hostile read that consumed the
// guard and silenced the first version), then writes 32 bytes at the watched offset. If the watch
// survives the read and reports the write, the mechanism is right.
fn main() {
    let layout = std::alloc::Layout::from_size_align(8192, 4096).unwrap();
    let base = unsafe { std::alloc::alloc_zeroed(layout) };
    println!("pid={}", std::process::id());
    println!("base={:p}", base);
    println!("field={:p}", unsafe { base.add(0x120) });
    std::io::stdout().flush().unwrap();

    // A few hostile reads of the page, at an offset away from the field.
    for i in 0..6 {
        std::thread::sleep(Duration::from_millis(400));
        unsafe { std::ptr::read_volatile(base.add(0x40)) };
        println!("read {i} at +0x40");
        std::io::stdout().flush().unwrap();
    }

    // Now the write that matters: 32 bytes, the shape of a key store. Twice, so the writer
    // instruction runs again and the hook installed on the first catch has something to report.
    std::thread::sleep(Duration::from_millis(300));
    let key = b"3df51fd02753d5605cc3139e66a3561e";
    unsafe { std::ptr::copy_nonoverlapping(key.as_ptr(), base.add(0x120), 32) };
    println!("WROTE the key at +0x120 (first)");
    std::io::stdout().flush().unwrap();

    std::thread::sleep(Duration::from_millis(1200));
    let key2 = b"7a1bc2d3e4f5061728394a5b6c7d8e9f";
    unsafe { std::ptr::copy_nonoverlapping(key2.as_ptr(), base.add(0x120), 32) };
    println!("WROTE the key at +0x120 (second)");
    std::io::stdout().flush().unwrap();

    std::thread::sleep(Duration::from_secs(4));
}

