import subprocess, threading, time, frida
SRC=r"C:\Users\Yonjay\AppData\Local\Temp\watchprobe\src\main.rs"
EXE=r"C:\Users\Yonjay\AppData\Local\Temp\watchprobe\wp6.exe"
JS = r"""
'use strict';
var page = ptr("__BASE__");
var ranges = [{ base: page, size: 0x1000 }];
var MODE = "__MODE__";
var hits = 0, writes = 0, rearmErr = null;
function handler(d) {
  hits++;
  if (d.operation === 'write') {
    var off = parseInt(d.address.and(ptr('0xfff')).toString(), 16);
    if (off >= 0x120 && off < 0x140) writes++;
  }
  if (MODE === 'defer') {
    // out of the callback, but as soon as the loop allows
    setTimeout(function () {
      try { MemoryAccessMonitor.disable(); } catch (e) {}
      try { MemoryAccessMonitor.enable(ranges, { onAccess: handler }); }
      catch (e) { rearmErr = String(e); }
    }, 0);
  }
}
function enable() { try { MemoryAccessMonitor.enable(ranges, { onAccess: handler }); } catch (e) {} }
enable();
if (MODE === 'timer') setInterval(function () {
  try { MemoryAccessMonitor.disable(); } catch (e) {}
  enable();
}, 100);
setInterval(function () { send({t:'stat', hits: hits, writes: writes, err: rearmErr}); }, 1000);
send({t:'armed'});
"""
def build():
    r=subprocess.run(['rustc','-O','-o',EXE,SRC],capture_output=True,text=True,encoding='utf-8',errors='replace')
    if r.returncode: print(r.stderr[-1500:]); raise SystemExit(1)
def run(mode, secs=17):
    p=subprocess.Popen([EXE],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)
    lines=[]; threading.Thread(target=lambda:[lines.append(l.rstrip()) for l in p.stdout],daemon=True).start()
    for _ in range(200):
        if len(lines)>=3: break
        time.sleep(0.02)
    pid=int(lines[0].split('=')[1]); base=lines[1].split('=')[1]
    s=frida.attach(pid); sc=s.create_script(JS.replace('__BASE__',base).replace('__MODE__',mode))
    got=[]; sc.on('message', lambda m,d: got.append(m)); sc.load(); time.sleep(secs)
    # how many writes did the target perform?
    time.sleep(0.1); s.detach(); p.kill()
    target_writes=len([l for l in lines if l.startswith('write')])
    last=[pl for m in got if (pl:=m.get('payload')) and pl.get('t')=='stat']
    st=last[-1] if last else {}
    print("%-8s target writes=%-4d  monitor: hits=%-5s field-writes=%-4s err=%s"
          % (mode, target_writes, st.get('hits'), st.get('writes'), st.get('err')))
build()
print("target does 24 stores at page+0x120, with reads of +0x40 in between\n")
for m in ('static','timer','defer'):
    run(m)

use std::io::Write;
use std::time::Duration;

// One 32-byte store at page+0x120 every ~600ms, with reads of page+0x40 in between -- the shape of a
// player that reads a context constantly and writes its key field once. The question is which
// re-arm strategy misses the fewest of those stores.
fn main() {
    let layout = std::alloc::Layout::from_size_align(8192, 4096).unwrap();
    let base = unsafe { std::alloc::alloc_zeroed(layout) };
    println!("pid={}", std::process::id());
    println!("base={:p}", base);
    println!("field={:p}", unsafe { base.add(0x120) });
    std::io::stdout().flush().unwrap();

    let mut n: u8 = 5;
    for i in 0..24 {
        // four reads, then one store -- reads far outnumber writes, as they do in the player
        for _ in 0..4 {
            unsafe { std::ptr::read_volatile(base.add(0x40)) };
            std::thread::sleep(Duration::from_millis(120));
        }
        unsafe { std::ptr::write_bytes(base.add(0x120), n, 32) };
        n = n.wrapping_add(1);
        println!("write #{i}");
        std::io::stdout().flush().unwrap();
        std::thread::sleep(Duration::from_millis(120));
    }
    std::thread::sleep(Duration::from_secs(2));
}

