238	function onAccess(d) {
239	  // The reporting cap must NOT short-circuit the catch below. The first version returned here once
240	  // the cap was reached, which on a busy page happened within seconds and left the watch armed,
241	  // re-arming and permanently deaf -- the same silent failure this script exists to avoid.
242	  if (found) return;
243	  reports++;
244	  var pg = d.address.and(ptr('0xfffffffffffff000')).toString();
245	  // parseInt, not .toNumber(): `.and()` yields a NativePointer, and NativePointer has no
246	  // toNumber() -- only UInt64 does. Calling it raises inside the callback, once per access, and the
247	  // watch then reports nothing at all while looking perfectly armed.
248	  var off = parseInt(d.address.and(ptr('0xfff')).toString(), 16);
249	  var hit = fieldAt(pg, off);
250	
251	  if (hit || reports <= INDIVIDUAL_CAP) {
252	    send({t: 'access', op: d.operation, off: '0x' + off.toString(16), page: pg,
253	          from: modOff(d.from), field: hit ? hit.file : null});
254	  }
255	
256	  if (d.operation === 'write' && hit) {
257	    found = true;
258	    if (timer) { clearInterval(timer); timer = null; }
259	    // Release every guard before reading: a read from the agent's own thread into a guarded page
260	    // raises `guard page was hit` instead of calling back. Measured, not assumed.
261	    try { MemoryAccessMonitor.disable(); } catch (e) {}
262	    send({t: 'write', by: modOff(d.from), from: d.from.toString(), file: hit.file,
263	          index: hit.index});
264	    // The value has to be read on a later turn of the loop, not here. A page guard faults BEFORE
265	    // the store executes -- the callback runs, and only when it returns does the instruction retry
266	    // and complete -- so reading the field inside the callback always returns the old contents.
267	    setTimeout(function () {
268	      var value = '<unreadable>';
269	      try { value = bytesToStr(ptr(hit.ctx).add(KEY_FIELD).readByteArray(32)); }
270	      catch (e) { value = '<' + e + '>'; }
271	      send({t: 'value', file: hit.file, index: hit.index, value: value});
272	    }, 0);
273	    // The access callback has the address but no thread context, so the registers and the backtrace
274	    // have to come from the instruction itself. Attaching once, after the fact, catches the next
275	    // store by the same instruction -- which is why it is guarded.
276	    if (!instrHooked) {
277	      instrHooked = true;
278	      try {
279	        Interceptor.attach(d.from, {
280	          onEnter: function () {
281	            // The instruction keeps running for every other context, so dump it a few times and
282	            // stop; the first one is the answer and the rest is noise.
283	            if (writerDumps++ >= 3) return;
284	            var ctx = this.context;
285	            var regs = {};
286	            ['rax','rbx','rcx','rdx','rsi','rdi','r8','r9','r10','r11'].forEach(function (rn) {
287	              try { regs[rn] = ctx[rn].toString(); } catch (e) {}
288	            });
289	            var stack = [];
290	            try { stack = stringsIn(ctx.rsp, 0x800); } catch (e) {}
291	            // ACCURATE needs unwind data and raises `invalid operation` where it is missing.
292	            var bt = [];
293	            try { bt = Thread.backtrace(ctx, Backtracer.ACCURATE).map(modOff); }
294	            catch (e) {
295	              try { bt = Thread.backtrace(ctx, Backtracer.FUZZY).map(modOff); } catch (e2) {}
296	            }
297	            var addrs = [];
298	            try { addrs = stackReturnAddrs(ctx.rsp, 0x400); } catch (e) {}
299	            send({t: 'writer', at: modOff(ctx.pc), regs: regs, stack: stack, bt: bt, addrs: addrs});
300	          }
301	        });
302	        send({t: 'log', msg: 'the writer instruction is now hooked; keep it playing and its ' +
303	              'registers will follow on the next run.'});
304	      } catch (e) { send({t: 'err', where: 'hook-writer', e: String(e)}); }
305	    }
306	    return;
307	  }
308	
309	  // Re-arm with a deferred turn, not synchronously here and not only on a timer.
310	  //
311	  // Synchronously re-enabling inside the callback WEDGES the target -- measured: 200 reports and
312	  // zero target operations for 8 seconds. Re-arming only on a 100 ms timer leaves a blind window in
313	  // which a store is simply not seen: on a target doing 24 stores with reads in between, the timer
