316	  // the primary mechanism and the timer below is only a safety net.
317	  scheduleRearm();
318	}
319	
320	var rearmPending = false;
321	function scheduleRearm() {
322	  if (rearmPending || found) return;
323	  rearmPending = true;
324	  setTimeout(function () {
325	    rearmPending = false;
326	    if (found) return;
327	    try { MemoryAccessMonitor.disable(); } catch (e) {}
328	    try { MemoryAccessMonitor.enable(ranges, { onAccess: onAccess }); }
329	    catch (e) { send({t: 'err', where: 're-arm', e: String(e)}); }
330	  }, 0);
331	}
332	
333	function arm() {
334	  try {
335	    MemoryAccessMonitor.enable(ranges, { onAccess: onAccess });
336	    // The safety net: if a deferred re-arm is ever lost, this restores the guard within a second.
337	    timer = setInterval(function () {
338	      if (found) { if (timer) { clearInterval(timer); timer = null; } return; }
339	      ticks++;
340	      try { MemoryAccessMonitor.disable(); } catch (e) {}
341	      try { MemoryAccessMonitor.enable(ranges, { onAccess: onAccess }); }
342	      catch (e) { send({t: 'err', where: 're-arm', e: String(e)}); }
343	      if (ticks % 20 === 0) {
344	        send({t: 'log', msg: 'still watching ' + ranges.length + ' page(s); ' + reports +
345	              ' access(es) seen so far'});
346	      }
347	    }, 1000);
348	  } catch (e) {
349	    send({t: 'err', where: 'arm', e: String(e)});
350	  }
351	}
352	
353	try {
354	  if (chooseTargets()) arm();
355	} catch (e) {
356	  send({t: 'err', where: 'setup', e: String(e)});
357	}
358	send({t: 'ready'});
359	"""
360	
361	
362	def find_pid():
363	    for p in frida.get_local_device().enumerate_processes():
364	        if p.name.lower() == 'evplayer2.exe':
365	            return p.pid
366	    return None
367	
368	
369	def main():
370	    secs = int(sys.argv[1]) if len(sys.argv) > 1 else 240
371	    pid = find_pid()
372	    if pid is None:
373	        print("EVPlayer2.exe is not running.")
374	        return 1
