382	        t = p.get('t')
383	        if t == 'log':
384	            print("[*] " + p['msg'], flush=True)
385	        elif t == 'access':
386	            mark = '  <<< lands on a key field' if p.get('field') else ''
387	            print("[access] %-5s page+%-6s from %s%s" % (p['op'], p['off'], p['from'], mark),
