391	            print("   instruction : %s" % p['by'], flush=True)
392	            print("   file        : %s  (index %s)" % (p['file'], p['index']), flush=True)
393	        elif t == 'value':
394	            print("   value now   : %s" % repr(p['value']), flush=True)
395	            print("   (read after the store completed, not during -- a guard faults before the "
396	                  "instruction runs)", flush=True)
397	        elif t == 'writer':
398	            print("\n=== the writer, with context ===", flush=True)
399	            print("   at    : %s" % p['at'], flush=True)
400	            for rn, v in (p.get('regs') or {}).items():
401	                print("   %s  : %s" % (rn, v), flush=True)
402	            if p.get('stack'):
403	                print("   stack strings: %s" % p['stack'][:30], flush=True)
404	            for i, fr in enumerate(p.get('bt') or []):
405	                print("   bt #%d %s" % (i, fr), flush=True)
406	            if not p.get('bt') and p.get('addrs'):
407	                print("   (no unwind-based backtrace; module pointers found on the stack instead)",
408	                      flush=True)
409	                for a in p['addrs'][:24]:
410	                    print("   %s" % a, flush=True)
411	        elif t == 'nodice':
412	            print("\n[!] %s" % p['msg'], flush=True)
413	        elif t == 'err':
414	            print("[err] %s: %s" % (p.get('where'), p.get('e')), flush=True)
415	        elif t == 'ready':
416	            print("[*] guards armed. 请保持播放。", flush=True)
417	
418	    script.on('message', on_message)
419	    script.load()
420	    try:
421	        time.sleep(secs)
422	    except KeyboardInterrupt:
423	        pass
424	    try:
425	        session.detach()
426	    except Exception:
427	        pass
428	    print("done.", flush=True)
429	    return 0
430	
431	
432	if __name__ == '__main__':
