use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

// The shape the probe_write.py rewrite is for, at the scale the real player has: many guarded pages,
// hammered by several threads, then one 32-byte store into each page's watched field.
//
// The earlier stand-in (src/main.rs) had ONE page, ONE thread and slept between stores. The rewrite
// claims that measuring the re-arm "free" on that target did not transfer to 24 hot Qt pages; this
// target is the one that can falsify that claim.
fn main() {
    const N: usize = 24;
    let layout = std::alloc::Layout::from_size_align(4096, 4096).unwrap();
    let mut addrs: Vec<usize> = Vec::new();
    for _ in 0..N {
        addrs.push(unsafe { std::alloc::alloc_zeroed(layout) } as usize);
    }
    println!("pid={}", std::process::id());
    for a in &addrs {
        println!("page={:x}", a);
    }
    std::io::stdout().flush().unwrap();

    // Four threads reading six pages each as fast as the machine allows -- no sleep, so the guard
    // churn is bounded only by the agent's own re-arm policy.
    let stop = Arc::new(AtomicBool::new(false));
    let mut handles = Vec::new();
    for t in 0..4usize {
        let pages = addrs.clone();
        let st = Arc::clone(&stop);
        handles.push(std::thread::spawn(move || {
            let mut i = t;
            while !st.load(Ordering::Relaxed) {
                for k in 0..6 {
                    let a = pages[(i + k) % pages.len()] as *const u8;
                    unsafe { std::ptr::read_volatile(a.add(0x40)) };
                }
                i += 1;
            }
        }));
    }
    std::thread::sleep(Duration::from_millis(12000));
    stop.store(true, Ordering::Relaxed);
    for h in handles {
        let _ = h.join();
    }

    println!("storm over; storing");
    std::io::stdout().flush().unwrap();
    let mut n: u8 = 7;
    for (i, a) in addrs.iter().enumerate() {
        unsafe { std::ptr::write_bytes((*a as *mut u8).add(0x120), n, 32) };
        println!("write #{}", i);
