function arm() {
  try {
    MemoryAccessMonitor.enable(ranges, { onAccess: onAccess });
    // This interval is both the safety-net re-arm and the only proof the run is alive. The heartbeat
    // fires on its FIRST tick and carries the running totals, so "capped but alive" is
    // distinguishable from "the agent stopped": a heartbeat with reports climbing and no key-field
    // hit is a real negative, while a heartbeat that never arrives makes the run void rather than a
    // statement about the player. Nothing here may be gated on reports or on a write.
    timer = setInterval(function () {
      if (found) return;
      send({t: 'hb', ticks: ticks, reports: reports, rearms: rearms, pages: ranges.length,
            pending: rearmPending, at: Date.now()});
      ticks++;
      try { MemoryAccessMonitor.disable(); } catch (e) {}
      try { MemoryAccessMonitor.enable(ranges, { onAccess: onAccess }); }
      catch (e) { send({t: 'err', where: 're-arm', e: String(e)}); }
    }, HEARTBEAT_MS);
  } catch (e) {
    send({t: 'err', where: 'arm', e: String(e)});
  }
}

